-- ===== quote-choices-local.sql =====
-- LOCAL ONLY. Explicit choices; never sends messages, charges or fiscal documents.
begin;
create table if not exists public.pro_quote_choices(
 quote_id uuid primary key references public.quotes(id) on delete cascade,owner_id uuid not null references public.profiles(id) on delete cascade,
 client_id uuid not null references public.profiles(id) on delete cascade,revision integer not null default 1,version integer not null default 1,
 base_items jsonb not null,extras jsonb not null,selected jsonb not null default '[]',tax_mode text not null,
 status text not null default 'open' check(status in ('open','accepted','declined')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.pro_quote_choice_versions(
 quote_id uuid not null references public.pro_quote_choices(quote_id) on delete cascade,version integer not null,base_items jsonb not null,extras jsonb not null,tax_mode text not null,at timestamptz not null default now(),primary key(quote_id,version)
);
create table if not exists public.pro_quote_choice_events(
 position bigint generated always as identity primary key,quote_id uuid not null references public.pro_quote_choices(quote_id) on delete cascade,
 actor_id uuid not null,action text not null,version integer not null,selected jsonb not null default '[]',total integer not null,at timestamptz not null default now()
);
create index if not exists pro_quote_choice_events_page on public.pro_quote_choice_events(quote_id,position desc);
create index if not exists pro_quote_choice_client_page on public.pro_quote_choices(client_id,quote_id);
create table if not exists public.pro_quote_choice_actions(actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,primary key(actor_id,action_id));
create or replace function public.pro_quote_choice_totals(p_items jsonb,p_tax text) returns jsonb language plpgsql immutable set search_path=public,pg_temp as $$
declare net numeric;tax numeric;begin
 select round(coalesce(sum((r->>'quantity')::numeric*(r->>'unit_price')::numeric),0)) into net from jsonb_array_elements(p_items) e(r);
 if net<0 or net>1000000000 then raise exception 'Quote amount limit' using errcode='22023';end if;
 tax:=case p_tax when 'mas_iva' then round(net*0.13) when 'incluido' then round(net-net/1.13) else 0 end;
 return jsonb_build_object('subtotal',net,'taxAmount',tax,'total',case when p_tax='mas_iva' then net+tax else net end);
end $$;
create or replace function public.pro_quote_choice_client(p_owner uuid,p_quote uuid) returns uuid language sql stable set search_path=public,pg_temp as $$
 select coalesce(q.client_id,(select a.client_user_id from pro_quote_links l join pro_work w on w.user_id=l.user_id and w."clientId"=l."clientId" join pro_appointment_requests a on a.owner_id=w.user_id and a.work_id=w.id and w."bookingClientId"=a.client_user_id::text where l.user_id=p_owner and l."quoteId"=q.id::text order by a.position desc limit 1))
 from quotes q join professionals p on p.id=q.professional_id and p.profile_id=p_owner where q.id=p_quote and q.deleted_at is null;
$$;
create or replace function public.pro_quote_choice_detail(p_actor uuid,p_quote uuid,p_after bigint default null) returns jsonb language plpgsql stable set search_path=public,pg_temp as $$
declare c pro_quote_choices;q quotes;owner uuid;recipient uuid;events jsonb;next_key bigint;totals jsonb;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select p.profile_id into owner from quotes r join professionals p on p.id=r.professional_id where r.id=p_quote and r.deleted_at is null;
 select * into q from quotes where id=p_quote and deleted_at is null;
 if owner is null then return null;end if;
 select * into c from pro_quote_choices where quote_id=p_quote;recipient:=coalesce(c.client_id,pro_quote_choice_client(owner,p_quote));
 if p_actor is distinct from owner and (c.quote_id is null or p_actor is distinct from recipient) then return null;end if;
 if p_after is not null and p_after<1 then raise exception 'Bad cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('position',position,'action',action,'version',version,'at',at,'selected',selected,'total',total) order by position desc),'[]') into events from(select * from pro_quote_choice_events where quote_id=p_quote and (p_after is null or position<p_after) order by position desc limit 20) s;
 if jsonb_array_length(events)=20 and exists(select 1 from pro_quote_choice_events where quote_id=p_quote and position<(events->19->>'position')::bigint) then next_key:=(events->19->>'position')::bigint;end if;
 totals:=pro_quote_choice_totals(q.items,q.tax_mode);
 return jsonb_build_object('quoteId',q.id,'title',coalesce(q.title,'Cotización'),'status',case when c.quote_id is null then q.status when q.status in ('withdrawn','declined') then q.status when c.status='open' and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then 'expired' else c.status end,'revision',coalesce(c.revision,0),'version',coalesce(c.version,0),'side',case when owner=p_actor then 'provider' else 'client' end,
 'canConfigure',q.status='sent' and (q.valid_until is null or q.valid_until>=(now() at time zone 'America/Costa_Rica')::date) and coalesce(c.status,'open')='open' and pro_appointment_enabled(owner) and not exists(select 1 from pro_invoice_drafts where user_id=owner and (quote_origin_key='quote:'||q.id::text or (source_kind='quote' and source_id=q.id::text))),
 'linked',recipient is not null and recipient<>owner,'configured',c.quote_id is not null,'baseItems',coalesce(c.base_items,q.items),'extras',coalesce(c.extras,'[]'),'selected',coalesce(c.selected,'[]'),'taxMode',q.tax_mode,'subtotal',totals->'subtotal','taxAmount',totals->'taxAmount','total',totals->'total','events',events,'nextCursor',next_key);
end $$;
create or replace function public.pro_quote_choice_page(p_actor uuid,p_after uuid default null,p_request uuid default null) returns jsonb language plpgsql stable set search_path=public,pg_temp as $$
declare result jsonb;next_key uuid;a pro_appointment_requests;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is not null then select * into a from pro_appointment_requests where id=p_request and p_actor in(owner_id,client_user_id);if not found then raise exception 'Forbidden' using errcode='42501';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('quoteId',id,'title',title,'status',status,'version',version,'total',total,'professionalName',professional_name) order by id desc),'[]') into result from(
 select q.id,coalesce(q.title,'Cotización') title,case when q.status in ('withdrawn','declined') then q.status when c.status='open' and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then 'expired' else c.status end status,c.version,q.total,coalesce(p.business_name,'Profesional') professional_name
 from pro_quote_choices c join quotes q on q.id=c.quote_id join professionals p on p.id=q.professional_id
 where q.deleted_at is null and (p_after is null or q.id<p_after) and ((p_request is null and c.client_id=p_actor) or (p_request is not null and c.owner_id=a.owner_id and c.client_id=a.client_user_id and exists(select 1 from pro_quote_links l join pro_work w on w.user_id=l.user_id and w."clientId"=l."clientId" where l.user_id=a.owner_id and l."quoteId"=q.id::text and w.id=a.work_id and w."bookingClientId"=a.client_user_id::text)))
 order by q.id desc limit 20) s;
 if jsonb_array_length(result)=20 then next_key:=(result->19->>'quoteId')::uuid;end if;
 return jsonb_build_object('items',result,'nextCursor',next_key);
end $$;
create or replace function public.pro_quote_choice_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if exists(select 1 from pro_quote_choices where quote_id=old.id) and (new.items is distinct from old.items or new.tax_mode is distinct from old.tax_mode or new.subtotal is distinct from old.subtotal or new.tax_amount is distinct from old.tax_amount or new.total is distinct from old.total or new.client_id is distinct from old.client_id or new.professional_id is distinct from old.professional_id or new.project_id is distinct from old.project_id or new.title is distinct from old.title or new.notes is distinct from old.notes or new.valid_until is distinct from old.valid_until or new.status is distinct from old.status and not(old.status='sent' and new.status='withdrawn')) and coalesce(current_setting('contratacr.quote_choice_write',true),'')<>'yes' then raise exception 'Use quote choice approval' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_quote_choice_guard on public.quotes;
create trigger pro_quote_choice_guard before update on public.quotes for each row execute function pro_quote_choice_guard();
create or replace function public.pro_quote_choice_invoice_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if exists(select 1 from pro_quote_choices c where c.owner_id=new.user_id and c.status='open' and ((new.source_kind='quote' and c.quote_id::text=new.source_id) or new.quote_origin_key='quote:'||c.quote_id::text or (new.source_kind='work' and exists(select 1 from pro_work w where w.user_id=new.user_id and w.id=new.source_id and w."externalQuoteId"=c.quote_id::text)))) then raise exception 'Customer must approve quote choices first' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_quote_choice_invoice_guard on public.pro_invoice_drafts;
create trigger pro_quote_choice_invoice_guard before insert on public.pro_invoice_drafts for each row execute function pro_quote_choice_invoice_guard();
create or replace function public.pro_quote_choice_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare q quotes;c pro_quote_choices;owner uuid;recipient uuid;prior pro_quote_choice_actions;action text;rid uuid;rev integer;extras jsonb;line jsonb;chosen jsonb;v_items jsonb;totals jsonb;result jsonb;v integer;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or not(p_input?&array['action','quoteId','actionId','revision']) or jsonb_typeof(p_input->'revision') is distinct from 'number' or p_input->>'revision'!~'^[0-9]{1,9}$' then raise exception 'Bad mutation' using errcode='22023';end if;
 action:=p_input->>'action';rid:=(p_input->>'quoteId')::uuid;rev:=(p_input->>'revision')::integer;
 select p.profile_id into owner from quotes r join professionals p on p.id=r.professional_id where r.id=rid and r.deleted_at is null;if owner is null then raise exception 'Not found' using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_quote_choice_actions where actor_id=p_actor and action_id=(p_input->>'actionId')::uuid;
 if found then if prior.input<>p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
 select * into q from quotes where id=rid for update;select * into c from pro_quote_choices where quote_id=rid for update;
 recipient:=coalesce(c.client_id,pro_quote_choice_client(owner,rid));
 if p_actor<>owner and (c.quote_id is null or p_actor is distinct from recipient) then raise exception 'Forbidden' using errcode='42501';end if;
 if rev<>coalesce(c.revision,0) then raise exception 'Changed quote' using errcode='40001';end if;
 if q.status<>'sent' or coalesce(c.status,'open')<>'open' then raise exception 'Closed quote' using errcode='40001';end if;
 if action='configure' then
  if p_actor<>owner or not pro_appointment_enabled(owner) then raise exception 'Forbidden' using errcode='42501';end if;
  if q.valid_until is not null and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then raise exception 'Expired quote' using errcode='40001';end if;
  if recipient is null or recipient=owner then raise exception 'Linked customer required' using errcode='22023';end if;
  if (p_input-array['action','quoteId','actionId','revision','extras'])<>'{}'::jsonb or jsonb_typeof(p_input->'extras') is distinct from 'array' or jsonb_array_length(p_input->'extras') not between 1 and 10 then raise exception 'Bad extras' using errcode='22023';end if;
  extras:=p_input->'extras';
  if (select count(distinct e->>'id') from jsonb_array_elements(extras)e)<>jsonb_array_length(extras) then raise exception 'Repeated extra' using errcode='22023';end if;
  for line in select value from jsonb_array_elements(extras) loop
   if jsonb_typeof(line) is distinct from 'object' or not(line?&array['id','description','quantity','unit_price']) or (line-array['id','description','quantity','unit_price'])<>'{}'::jsonb or jsonb_typeof(line->'description') is distinct from 'string' or length(btrim(line->>'description')) not between 1 and 140 or jsonb_typeof(line->'quantity') is distinct from 'number' or (line->>'quantity')!~'^[0-9]{1,4}(\.[0-9]{1,2})?$' or (line->>'quantity')::numeric<=0 or (line->>'quantity')::numeric>9999 or jsonb_typeof(line->'unit_price') is distinct from 'number' or (line->>'unit_price')!~'^[0-9]{1,9}$' or (line->>'unit_price')::numeric>100000000 then raise exception 'Invalid extra' using errcode='22023';end if;
   perform (line->>'id')::uuid;
  end loop;
  if jsonb_array_length(q.items)+jsonb_array_length(extras)>20 or exists(select 1 from pro_invoice_drafts where user_id=owner and (quote_origin_key='quote:'||q.id::text or (source_kind='quote' and source_id=q.id::text))) then raise exception 'Quote already invoiced or too many lines' using errcode='22023';end if;
  perform pro_quote_choice_totals(coalesce(c.base_items,q.items)||extras,q.tax_mode);
  v:=coalesce(c.version,0)+1;
  insert into pro_quote_choices(quote_id,owner_id,client_id,base_items,extras,tax_mode) values(rid,owner,recipient,q.items,extras,q.tax_mode) on conflict(quote_id) do update set extras=excluded.extras,revision=c.revision+1,version=v,updated_at=now();
  insert into pro_quote_choice_versions values(rid,v,coalesce(c.base_items,q.items),extras,q.tax_mode,now());
  totals:=pro_quote_choice_totals(q.items,q.tax_mode);chosen:='[]';
 elsif action in ('accept','decline') then
  if p_actor is distinct from recipient or c.quote_id is null then raise exception 'Only customer may approve' using errcode='42501';end if;
  if (p_input-array['action','quoteId','actionId','revision','selected'])<>'{}'::jsonb or action='decline' and p_input?'selected' then raise exception 'Unexpected fields' using errcode='22023';end if;
  if action='accept' and exists(select 1 from pro_invoice_drafts where user_id=owner and (quote_origin_key='quote:'||q.id::text or (source_kind='quote' and source_id=q.id::text))) then raise exception 'Invoice draft already exists' using errcode='40001';end if;
  if action='accept' and not pro_appointment_enabled(owner) then raise exception 'Provider unavailable' using errcode='42501';end if;
  if action='accept' and q.valid_until is not null and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then raise exception 'Expired quote' using errcode='40001';end if;
  chosen:=case when action='accept' then p_input->'selected' else '[]'::jsonb end;
  if jsonb_typeof(chosen) is distinct from 'array' or jsonb_array_length(chosen)>10 or exists(select 1 from jsonb_array_elements(chosen)e where jsonb_typeof(e)<>'string') or (select count(distinct e) from jsonb_array_elements(chosen)e)<>jsonb_array_length(chosen) or exists(select 1 from jsonb_array_elements_text(chosen)e where not exists(select 1 from jsonb_array_elements(c.extras)x where x->>'id'=e)) then raise exception 'Invalid selection' using errcode='22023';end if;
  select c.base_items||coalesce(jsonb_agg(jsonb_build_object('description',x->>'description','quantity',x->'quantity','unit_price',x->'unit_price') order by n),'[]') into v_items from jsonb_array_elements(c.extras) with ordinality e(x,n) where chosen ? (x->>'id');
  totals:=pro_quote_choice_totals(v_items,c.tax_mode);
  perform set_config('contratacr.quote_choice_write','yes',true);
  if action='accept' then update quotes set items=v_items,subtotal=(totals->>'subtotal')::integer,tax_amount=(totals->>'taxAmount')::integer,total=(totals->>'total')::integer,status='accepted',accepted_at=now(),updated_at=now() where id=rid;
  else update quotes set status='declined',declined_at=now(),updated_at=now() where id=rid;end if;
  perform set_config('contratacr.quote_choice_write','',true);
  update pro_quote_choices set status=case action when 'accept' then 'accepted' else 'declined' end,selected=chosen,revision=revision+1,updated_at=now() where quote_id=rid;v:=c.version;
 else raise exception 'Bad action' using errcode='22023';end if;
 insert into pro_quote_choice_events(quote_id,actor_id,action,version,selected,total) values(rid,p_actor,action,v,chosen,(totals->>'total')::integer);
 select jsonb_build_object('quoteId',rid,'revision',revision,'version',version,'status',status) into result from pro_quote_choices where quote_id=rid;
 insert into pro_quote_choice_actions values(p_actor,(p_input->>'actionId')::uuid,p_input,result);return result;
end $$;
do $$declare n text;begin foreach n in array array['pro_quote_choices','pro_quote_choice_versions','pro_quote_choice_events','pro_quote_choice_actions'] loop execute format('alter table %I enable row level security',n);execute format('revoke all on %I from public,anon,authenticated',n);execute format('grant all on %I to service_role',n);end loop;end $$;
grant usage,select on sequence public.pro_quote_choice_events_position_seq to service_role;
revoke all on function pro_quote_choice_totals(jsonb,text),pro_quote_choice_client(uuid,uuid),pro_quote_choice_detail(uuid,uuid,bigint),pro_quote_choice_page(uuid,uuid,uuid),pro_quote_choice_guard(),pro_quote_choice_invoice_guard(),pro_quote_choice_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_quote_choice_totals(jsonb,text),pro_quote_choice_client(uuid,uuid),pro_quote_choice_detail(uuid,uuid,bigint),pro_quote_choice_page(uuid,uuid,uuid),pro_quote_choice_guard(),pro_quote_choice_invoice_guard(),pro_quote_choice_mutate(uuid,jsonb) to service_role;
commit;

-- ===== quote-change-requests-local.sql =====
-- LOCAL PRO ONLY. Append-only discussion; never changes quotes or sends messages.
begin;
create table if not exists public.pro_quote_change_state(
 quote_id uuid primary key references public.quotes(id) on delete cascade,
 owner_id uuid not null references public.profiles(id) on delete cascade,
 client_id uuid not null references public.profiles(id) on delete cascade,
 revision integer not null default 0,pending boolean not null default false
);
create table if not exists public.pro_quote_change_events(
 position bigint generated always as identity primary key,quote_id uuid not null references public.pro_quote_change_state(quote_id) on delete cascade,
 actor_id uuid not null,action text not null check(action in ('request','respond','cancel')),note text not null check(length(btrim(note)) between 1 and 1000),
 snapshot jsonb not null,at timestamptz not null default now()
);
create index if not exists pro_quote_change_events_page on public.pro_quote_change_events(quote_id,position desc);
create table if not exists public.pro_quote_change_actions(actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,primary key(actor_id,action_id));
create or replace function public.pro_quote_change_snapshot(p_quote uuid) returns jsonb language sql stable set search_path=public,pg_temp as $$
 select jsonb_build_object('title',q.title,'items',q.items,'taxMode',q.tax_mode,'subtotal',q.subtotal,'taxAmount',q.tax_amount,'total',q.total,'notes',q.notes,'validUntil',q.valid_until,'status',q.status,'choices',(select jsonb_build_object('version',c.version,'baseItems',c.base_items,'extras',c.extras,'selected',c.selected) from pro_quote_choices c where c.quote_id=q.id)) from quotes q where q.id=p_quote and q.deleted_at is null;
$$;
create or replace function public.pro_quote_change_read(p_actor uuid,p_quote uuid,p_after bigint default null) returns jsonb language plpgsql stable set search_path=public,pg_temp as $$
declare q quotes;s pro_quote_change_state;owner uuid;recipient uuid;events jsonb;snapshot jsonb;enabled boolean;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into q from quotes where id=p_quote and deleted_at is null;if not found then return null;end if;
 select profile_id into owner from professionals where id=q.professional_id;recipient:=pro_quote_choice_client(owner,p_quote);
 if p_actor is distinct from owner and p_actor is distinct from recipient then return null;end if;
 select * into s from pro_quote_change_state where quote_id=p_quote;
 if s.quote_id is not null and (s.owner_id is distinct from owner or s.client_id is distinct from recipient) then raise exception 'Changed recipient' using errcode='42501';end if;
 enabled:=pro_appointment_enabled(owner) and recipient is not null and recipient<>owner;
 if p_after is not null and p_after<1 then raise exception 'Bad cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('position',position,'action',action,'note',note,'snapshot',e.snapshot,'at',at) order by position desc),'[]') into events from(select * from pro_quote_change_events where quote_id=p_quote and (p_after is null or position<p_after) order by position desc limit 21) e;
 snapshot:=pro_quote_change_snapshot(p_quote);
 return jsonb_build_object('quoteId',p_quote,'enabled',enabled or s.quote_id is not null,'side',case when p_actor=owner then 'provider' else 'client' end,'revision',coalesce(s.revision,0),'pending',coalesce(s.pending,false),'canWrite',enabled and q.status='sent' and (q.valid_until is null or q.valid_until>=(now() at time zone 'America/Costa_Rica')::date),'fingerprint',md5(snapshot::text),'events',(select coalesce(jsonb_agg(e order by n),'[]') from jsonb_array_elements(events) with ordinality t(e,n) where n<=20),'nextCursor',case when jsonb_array_length(events)>20 then (events->19->>'position')::bigint else null end);
end $$;
create or replace function public.pro_quote_change_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare q quotes;s pro_quote_change_state;owner uuid;recipient uuid;prior pro_quote_change_actions;rid uuid;action text;note text;snapshot jsonb;result jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or not(p_input?&array['quoteId','actionId','action','revision','fingerprint','note']) or (p_input-array['quoteId','actionId','action','revision','fingerprint','note'])<>'{}'::jsonb or jsonb_typeof(p_input->'revision') is distinct from 'number' or p_input->>'revision'!~'^[0-9]{1,9}$' or jsonb_typeof(p_input->'note') is distinct from 'string' or length(btrim(p_input->>'note')) not between 1 and 1000 or p_input->>'action' not in ('request','respond','cancel') then raise exception 'Invalid input' using errcode='22023';end if;
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 rid:=(p_input->>'quoteId')::uuid;action:=p_input->>'action';note:=btrim(p_input->>'note');
 select p.profile_id into owner from quotes r join professionals p on p.id=r.professional_id where r.id=rid and r.deleted_at is null;if owner is null then raise exception 'Not found' using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_quote_change_actions where actor_id=p_actor and action_id=(p_input->>'actionId')::uuid;
 if found then if prior.input<>p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
 select * into q from quotes where id=rid and deleted_at is null for update;if not found then raise exception 'Not found' using errcode='P0002';end if;
 select profile_id into owner from professionals where id=q.professional_id;recipient:=pro_quote_choice_client(owner,rid);
 if p_actor is distinct from owner and p_actor is distinct from recipient then raise exception 'Forbidden' using errcode='42501';end if;
 if not pro_appointment_enabled(owner) or recipient is null or recipient=owner then raise exception 'Pro required' using errcode='42501';end if;
 insert into pro_quote_change_state(quote_id,owner_id,client_id) values(rid,owner,recipient) on conflict do nothing;
 select * into s from pro_quote_change_state where quote_id=rid for update;
 if s.owner_id is distinct from owner or s.client_id is distinct from recipient then raise exception 'Changed recipient' using errcode='42501';end if;
 snapshot:=pro_quote_change_snapshot(rid);
 if s.revision<>(p_input->>'revision')::integer or md5(snapshot::text) is distinct from p_input->>'fingerprint' then raise exception 'Changed quote' using errcode='40001';end if;
 if q.status<>'sent' or q.valid_until<(now() at time zone 'America/Costa_Rica')::date then raise exception 'Closed quote' using errcode='40001';end if;
 if action='request' then
  if p_actor<>recipient then raise exception 'Only customer' using errcode='42501';end if;
  if s.pending then raise exception 'Request already pending' using errcode='40001';end if;
 elsif action='respond' then
  if p_actor<>owner then raise exception 'Only professional' using errcode='42501';end if;
  if not s.pending then raise exception 'No pending request' using errcode='40001';end if;
 else
  if p_actor<>recipient then raise exception 'Only customer' using errcode='42501';end if;
  if not s.pending then raise exception 'No pending request' using errcode='40001';end if;
 end if;
 insert into pro_quote_change_events(quote_id,actor_id,action,note,snapshot) values(rid,p_actor,action,note,snapshot);
 update pro_quote_change_state set revision=revision+1,pending=action='request' where quote_id=rid;
 select jsonb_build_object('quoteId',rid,'revision',revision,'pending',pending) into result from pro_quote_change_state where quote_id=rid;
 insert into pro_quote_change_actions values(p_actor,(p_input->>'actionId')::uuid,p_input,result);return result;
end $$;
create or replace function public.pro_quote_change_recipient_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if (new.professional_id is distinct from old.professional_id or new.client_id is distinct from old.client_id) and exists(select 1 from pro_quote_change_state where quote_id=old.id) then raise exception 'Retain quote discussion recipients' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_quote_change_recipient_guard on public.quotes;
create trigger pro_quote_change_recipient_guard before update on public.quotes for each row execute function pro_quote_change_recipient_guard();
do $$declare n text;begin foreach n in array array['pro_quote_change_state','pro_quote_change_events','pro_quote_change_actions'] loop execute format('alter table %I enable row level security',n);execute format('revoke all on %I from public,anon,authenticated',n);execute format('grant all on %I to service_role',n);end loop;end $$;
grant usage,select on sequence public.pro_quote_change_events_position_seq to service_role;
revoke all on function pro_quote_change_snapshot(uuid),pro_quote_change_read(uuid,uuid,bigint),pro_quote_change_mutate(uuid,jsonb),pro_quote_change_recipient_guard() from public,anon,authenticated;
grant execute on function pro_quote_change_snapshot(uuid),pro_quote_change_read(uuid,uuid,bigint),pro_quote_change_mutate(uuid,jsonb),pro_quote_change_recipient_guard() to service_role;
commit;

-- ===== work-changes-local.sql =====
-- LOCAL PRO ONLY. Explicit approved commercial changes; no fiscal issuance or sends.
begin;
create table if not exists public.pro_work_changes(
 owner_id uuid not null references profiles(id) on delete cascade,
 id uuid not null, work_id text not null, client_user_id uuid references profiles(id) on delete set null,
 position bigint generated always as identity,
 reason text not null check(length(reason) between 1 and 500),lines jsonb not null check(jsonb_typeof(lines)='array' and jsonb_array_length(lines) between 1 and 20),
 base_cents bigint not null check(base_cents between 0 and 10000000000),base_position bigint not null,
 delta_cents bigint not null,total_cents bigint not null check(total_cents between 0 and 10000000000),
 status text not null default 'proposed' check(status in('proposed','accepted','declined','withdrawn')),
 revision integer not null default 1,recorded_by text check(recorded_by in('provider','client')),acceptance_note text not null default '' check(length(acceptance_note)<=500),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade,
 check(total_cents=base_cents+delta_cents)
);
create unique index if not exists pro_work_change_global_id on public.pro_work_changes(id);
create unique index if not exists pro_work_change_pending on public.pro_work_changes(owner_id,work_id) where status='proposed';
create index if not exists pro_work_change_page on public.pro_work_changes(owner_id,work_id,position desc);
create table if not exists public.pro_work_change_actions(
 owner_id uuid not null references profiles(id) on delete cascade,actor_id uuid not null references profiles(id) on delete cascade,
 id uuid not null,input jsonb not null,result jsonb not null,primary key(owner_id,actor_id,id)
);
create or replace function public.pro_work_changes_enabled(p_owner uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql).
 select public.pro_entitled(p_owner);
$$;
create or replace function public.pro_work_changes_page(p_actor uuid,p_work text default '',p_request uuid default null,p_after bigint default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w pro_work;a jsonb;owner uuid;side text;result jsonb;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after<1 then raise exception 'Invalid cursor' using errcode='22023';end if;
 if p_request is not null then
  select x.* into w from pro_appointment_requests r join pro_work x on x.user_id=r.owner_id and x.id=r.work_id and x."bookingClientId"=r.client_user_id::text where r.id=p_request and p_actor in(r.owner_id,r.client_user_id);
 else select * into w from pro_work where user_id=p_actor and id=p_work;end if;
 if w.id is null then return null;end if;owner:=w.user_id;side:=case when p_actor=owner then 'provider' else 'client' end;
 a:=pro_work_account(owner,w.id);
 with page as(select * from pro_work_changes where owner_id=owner and work_id=w.id and (side='provider' or client_user_id=p_actor) and (p_after is null or position<p_after) order by position desc limit 21)
 select jsonb_build_object('side',side,'workId',w.id,'service',w.service,'clientLinked',w."bookingClientId" is not null,'canPropose',side='provider' and pro_work_changes_enabled(owner) and not w.cancelled and a->>'agreedCents' is not null,
 'account',jsonb_build_object('agreedCents',a->'agreedCents','paidCents',a->'paidCents','balanceCents',a->'balanceCents'),
 'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'position',position,'reason',reason,'lines',lines,'baseCents',base_cents,'deltaCents',delta_cents,'totalCents',total_cents,'status',status,'stale',status='proposed' and base_position is distinct from (select coalesce(max(e.position),0) from pro_client_entries e where e.user_id=owner and e.work_id=w.id and e.kind='agreement'),'revision',revision,'recordedBy',recorded_by,'acceptanceNote',acceptance_note,'createdAt',created_at,'updatedAt',updated_at) order by position desc) from(select * from page limit 20)t),'[]'),
 'nextCursor',case when(select count(*) from page)>20 then(select position from page offset 19 limit 1) else null end) into result;
 return result;
end $$;
create or replace function public.pro_work_changes_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare owner uuid;w pro_work;c pro_clients;r pro_work_changes;prior pro_work_change_actions;act text:=p_input->>'action';rid uuid:=(p_input->>'id')::uuid;aid uuid:=(p_input->>'actionId')::uuid;a jsonb;delta bigint:=0;v bigint;entry jsonb;amount numeric;latest bigint;result jsonb;is_owner boolean;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if act='propose' then owner:=p_actor;else select owner_id into owner from pro_work_changes where id=rid and p_actor in(owner_id,client_user_id);end if;
 if owner is null or rid is null or aid is null or act not in('propose','accept','decline','withdraw','record_acceptance') then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_work_change_actions where owner_id=owner and actor_id=p_actor and id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Request changed' using errcode='22023';end if;return prior.result;end if;
 is_owner:=p_actor=owner;
 if act not in('decline','withdraw') and not pro_work_changes_enabled(owner) then raise exception 'Pro required' using errcode='42501';end if;
 if act='propose' then select * into w from pro_work where user_id=owner and id=p_input->>'workId' for update;
 else select * into r from pro_work_changes where owner_id=owner and id=rid for update;select * into w from pro_work where user_id=owner and id=r.work_id for update;
  if r.revision<>(p_input->>'revision')::integer or r.status<>'proposed' then raise exception 'Changed' using errcode='40001';end if;
  if not is_owner and w."bookingClientId" is distinct from p_actor::text then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 if w.id is null then raise exception 'Unavailable work' using errcode='42501';end if;
 select * into c from pro_clients where user_id=owner and id=w."clientId";
 a:=pro_work_account(owner,w.id);
 select coalesce(max(position),0) into latest from pro_client_entries where user_id=owner and work_id=w.id and kind='agreement';
 if act='propose' then
  if not is_owner or w.cancelled or c.archived or a->>'agreedCents' is null then raise exception 'Set an active agreement first' using errcode='22023';end if;
  if (a->>'agreedCents')::bigint<>(p_input->>'baseCents')::bigint then raise exception 'Agreement changed' using errcode='40001';end if;
  if jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_array_length(p_input->'lines') not between 1 and 20 or length(btrim(p_input->>'reason')) not between 1 and 500 then raise exception 'Invalid change' using errcode='22023';end if;
  if (select count(*) from pro_work_changes where owner_id=owner and work_id=w.id)>=500 then raise exception 'History limit' using errcode='54000';end if;
  for entry in select value from jsonb_array_elements(p_input->'lines') loop
   amount:=(entry->>'amountCents')::numeric;
   if jsonb_typeof(entry->'description') is distinct from 'string' or length(btrim(entry->>'description')) not between 1 and 160 or amount is null or amount<>round(amount) or amount=0 or abs(amount)>10000000000 then raise exception 'Invalid line' using errcode='22023';end if;
   delta:=delta+amount::bigint;
  end loop;
  amount:=(a->>'agreedCents')::bigint+delta;
  if amount<0 or amount>10000000000 or amount<(a->>'paidCents')::bigint then raise exception 'Invalid total or below received payments' using errcode='22023';end if;
  insert into pro_work_changes(owner_id,id,work_id,client_user_id,reason,lines,base_cents,base_position,delta_cents,total_cents)
  values(owner,rid,w.id,nullif(w."bookingClientId",'')::uuid,btrim(p_input->>'reason'),p_input->'lines',(a->>'agreedCents')::bigint,latest,delta,amount::bigint) returning * into r;
 else
  if act='withdraw' and not is_owner or act in('accept','decline') and is_owner or act='record_acceptance' and not is_owner then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('accept','record_acceptance') then
   if w.cancelled or c.archived or latest<>r.base_position or (a->>'agreedCents')::bigint is distinct from r.base_cents or r.total_cents<(a->>'paidCents')::bigint then raise exception 'Agreement or balance changed' using errcode='40001';end if;
   if act='record_acceptance' and length(btrim(p_input->>'note')) not between 10 and 500 then raise exception 'Explain external approval' using errcode='22023';end if;
   select revision into v from pro_workspace_core where user_id=owner;
   perform pro_record_client_operation(owner,jsonb_build_object('actionId',aid,'clientId',w."clientId",'workId',w.id,'kind','agreement','amountCents',r.total_cents,'note',left('Cambio aprobado: '||r.reason,160)),v::integer);
  end if;
  update pro_work_changes set status=case when act in('accept','record_acceptance') then 'accepted' when act='decline' then 'declined' else 'withdrawn' end,
   revision=revision+1,recorded_by=case when act in('accept','record_acceptance') then case when is_owner then 'provider' else 'client' end end,
   acceptance_note=case when act='record_acceptance' then btrim(p_input->>'note') else '' end,updated_at=now() where owner_id=owner and id=rid returning * into r;
 end if;
 result:=jsonb_build_object('id',r.id,'revision',r.revision,'status',r.status);
 insert into pro_work_change_actions(owner_id,actor_id,id,input,result) values(owner,p_actor,aid,p_input,result);
 return result;
end $$;
alter table public.pro_work_changes enable row level security;
alter table public.pro_work_change_actions enable row level security;
revoke all on public.pro_work_changes,public.pro_work_change_actions from public,anon,authenticated;
grant all on public.pro_work_changes,public.pro_work_change_actions to service_role;
grant usage,select on sequence public.pro_work_changes_position_seq to service_role;
revoke all on function public.pro_work_changes_enabled(uuid),public.pro_work_changes_page(uuid,text,uuid,bigint),public.pro_work_changes_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_changes_enabled(uuid),public.pro_work_changes_page(uuid,text,uuid,bigint),public.pro_work_changes_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== appointment-reschedule-local.sql =====
-- LOCAL PRO ONLY. Retain the confirmed slot until the customer accepts a new one.
-- No notifications, new work, charges, materials, or invoice rewrites.
begin;
create table if not exists public.pro_appointment_reschedules(
 id uuid primary key,position bigint generated always as identity unique,
 request_id uuid not null references pro_appointment_requests(id) on delete cascade,
 owner_id uuid not null references profiles(id) on delete cascade,
 work_id text not null,client_user_id uuid not null references profiles(id) on delete cascade,
 from_start timestamptz not null,from_end timestamptz not null,
 start_at timestamptz not null,duration_minutes integer not null check(duration_minutes between 15 and 480 and duration_minutes%15=0),
 note text not null default '' check(length(note)<=500),request_revision integer not null check(request_revision>=0),
 status text not null default 'proposed' check(status in('proposed','accepted','declined','withdrawn')),
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 foreign key(owner_id,work_id) references pro_work(user_id,id),check(from_end>from_start)
);
create unique index if not exists pro_appointment_reschedule_pending on pro_appointment_reschedules(request_id) where status='proposed';
create index if not exists pro_appointment_reschedule_page on pro_appointment_reschedules(request_id,position desc);
create table if not exists public.pro_appointment_reschedule_actions(
 actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,
 request_id uuid not null references pro_appointment_requests(id) on delete cascade,
 input jsonb not null,result jsonb not null,primary key(actor_id,action_id)
);
create or replace function public.pro_appointment_reschedule_slot_free(p_owner uuid,p_work text,p_start timestamptz,p_duration integer) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(p_start>now()+make_interval(mins=>coalesce(s.notice_minutes,15)) and p_start<now()+interval '90 days'
 and p_duration between 15 and 480 and p_duration%15=0
 and extract(second from p_start)=0 and extract(minute from p_start)::integer%15=0
 and exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>=p_start+make_interval(mins=>p_duration))
 and not exists(select 1 from pro_work w where w.user_id=p_owner and w.id<>p_work and not w.cancelled and pro_instant(w.start)<p_start+make_interval(mins=>p_duration+coalesce(s.buffer_minutes,0)) and pro_instant(w."end")>p_start-make_interval(mins=>coalesce(s.buffer_minutes,0))),false)
 from (select 1) anchor left join pro_visit_settings s on s.owner_id=p_owner;
$$;
create or replace function public.pro_appointment_reschedule_page(p_actor uuid,p_request uuid,p_after bigint default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;w pro_work;result jsonb;side text;active boolean;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after<1 then raise exception 'Invalid cursor' using errcode='22023';end if;
 select * into r from pro_appointment_requests where id=p_request and p_actor in(owner_id,client_user_id);if not found or r.work_id is null then return null;end if;
 select * into w from pro_work where user_id=r.owner_id and id=r.work_id and "bookingClientId"=r.client_user_id::text;if not found then return null;end if;
 side:=case when p_actor=r.owner_id then 'provider' else 'client' end;
 active:=r.status='confirmed' and not w.cancelled and w.stage='scheduled' and pro_instant(w.start)>now();
 with page as(select * from pro_appointment_reschedules where request_id=p_request and (p_after is null or position<p_after) order by position desc limit 21)
 select jsonb_build_object('requestId',p_request,'side',side,'requestRevision',r.revision,
 'current',jsonb_build_object('start',pro_appointment_time(pro_instant(w.start)),'end',pro_appointment_time(pro_instant(w."end")),'durationMinutes',extract(epoch from(pro_instant(w."end")-pro_instant(w.start)))::integer/60),
 'canPropose',side='provider' and active and pro_appointment_enabled(r.owner_id) and not exists(select 1 from pro_appointment_reschedules where request_id=p_request and status='proposed'),
 'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'position',position,'revision',revision,'status',status,
 'stale',case when status='proposed' then not active or not pro_appointment_enabled(r.owner_id) or request_revision<>r.revision or from_start is distinct from pro_instant(w.start) or from_end is distinct from pro_instant(w."end") or not pro_appointment_reschedule_slot_free(r.owner_id,r.work_id,start_at,duration_minutes) else false end,
 'fromStart',pro_appointment_time(from_start),'fromEnd',pro_appointment_time(from_end),'start',pro_appointment_time(start_at),'end',pro_appointment_time(start_at+make_interval(mins=>duration_minutes)),
 'durationMinutes',duration_minutes,'note',note,'requestRevision',request_revision,'createdAt',created_at,'updatedAt',updated_at) order by position desc) from(select * from page order by position desc limit 20)p),'[]'),
 'nextCursor',case when(select count(*) from page)>20 then(select position from page order by position desc offset 19 limit 1) else null end) into result;
 return result;
end $$;
create or replace function public.pro_appointment_reschedule_slots(p_actor uuid,p_request uuid,p_day date,p_duration integer) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;w pro_work;first_at timestamptz;last_at timestamptz;slots jsonb;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_day is null or p_day<(now() at time zone 'America/Costa_Rica')::date or p_day>(now() at time zone 'America/Costa_Rica')::date+90 or p_duration is null or p_duration<15 or p_duration>480 or p_duration%15<>0 then raise exception 'Invalid day or duration' using errcode='22023';end if;
 select * into r from pro_appointment_requests where id=p_request and p_actor in(owner_id,client_user_id);if not found or r.work_id is null then return null;end if;
 select * into w from pro_work where user_id=r.owner_id and id=r.work_id and "bookingClientId"=r.client_user_id::text;if not found then return null;end if;
 if r.status<>'confirmed' or w.cancelled or w.stage<>'scheduled' or pro_instant(w.start)<=now() or not pro_appointment_enabled(r.owner_id) then return jsonb_build_object('slots','[]'::jsonb,'truncated',false);end if;
 first_at:=p_day::timestamp at time zone 'America/Costa_Rica';last_at:=(p_day+1)::timestamp at time zone 'America/Costa_Rica';
 select coalesce(jsonb_agg(jsonb_build_object('start',pro_appointment_time(t),'end',pro_appointment_time(t+make_interval(mins=>p_duration))) order by t),'[]') into slots
 from generate_series(first_at,last_at-interval '15 minutes',interval '15 minutes') t where pro_appointment_reschedule_slot_free(r.owner_id,r.work_id,t,p_duration);
 return jsonb_build_object('slots',slots,'truncated',false);
end $$;
-- Only a transaction accepting this exact pending proposal can alter its linked time.
-- The original service/client/account linkage protections remain in force.
create or replace function public.pro_appointment_sync_work() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare r pro_appointment_requests;new_status text;event_action text;proposal pro_appointment_reschedules;flag text;
begin
 if not exists(select 1 from pro_appointment_requests where owner_id=new.user_id and work_id=new.id) then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,0));
 select * into r from pro_appointment_requests where owner_id=new.user_id and work_id=new.id for update;
 -- Round 1: a job linked by invitation keeps its own lifecycle (any stage, dates and service);
 -- only the customer of the job cannot change while an account is linked to it.
 if r.origin='project_invite' then
  if new."clientId" is distinct from old."clientId" and r.status in('confirmed','completed') then raise exception 'Unlink the customer account first' using errcode='23514',hint='pro_invite_client_change';end if;
  return new;
 end if;
 if current_setting('contratacr.appointment_request',true)=r.id::text then return new;end if;
 if new.service is distinct from old.service or new."clientId" is distinct from old."clientId" or new."bookingClientId" is distinct from old."bookingClientId" then raise exception 'Use the appointment agreement workflow' using errcode='23514';end if;
 if new.start is distinct from old.start or new."end" is distinct from old."end" then
  flag:=current_setting('contratacr.appointment_reschedule',true);
  select * into proposal from pro_appointment_reschedules where id::text=flag and request_id=r.id and owner_id=new.user_id and work_id=new.id and client_user_id=r.client_user_id and status='proposed';
  if not found or r.status<>'confirmed' or r.revision<>proposal.request_revision or old.cancelled or old.stage<>'scheduled' or new.cancelled is distinct from old.cancelled or new.stage is distinct from old.stage
   or pro_instant(old.start) is distinct from proposal.from_start or pro_instant(old."end") is distinct from proposal.from_end or pro_instant(old.start)<=now()
   or pro_instant(new.start) is distinct from proposal.start_at or pro_instant(new."end") is distinct from proposal.start_at+make_interval(mins=>proposal.duration_minutes) then raise exception 'Use the appointment agreement workflow' using errcode='23514';end if;
  return new;
 end if;
 if new.cancelled is not distinct from old.cancelled and new.stage is not distinct from old.stage then return new;end if;
 if r.status in ('cancelled','completed') or (not new.cancelled and new.stage not in ('scheduled','completed')) then raise exception 'Appointment state cannot be reopened' using errcode='23514';end if;
 if new.cancelled and pro_instant(new.start)<=now() then raise exception 'Appointment already started' using errcode='23514';end if;
 new_status:=case when new.cancelled then 'cancelled' when new.stage='completed' then 'completed' else 'confirmed' end;event_action:=case when new.cancelled then 'cancel' when new.stage='completed' then 'completed' else 'agenda_updated' end;
 update pro_appointment_requests set status=new_status,revision=revision+1,updated_at=now() where id=r.id;
 insert into pro_appointment_events(request_id,actor_id,side,action,start_at,end_at,status) values(r.id,r.owner_id,'provider',event_action,pro_instant(new.start),pro_instant(new."end"),new_status);
 return new;
end $$;
create or replace function public.pro_appointment_reschedule_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;rid uuid;aid uuid;request uuid;owner uuid;r pro_appointment_requests;w pro_work;p pro_appointment_reschedules;prior pro_appointment_reschedule_actions;keys text[];required text[];start_at timestamptz;duration integer;result jsonb;prior_flag text;
begin
 if p_actor is null or jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['action','requestId','id','actionId']) or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';rid:=(p_input->>'id')::uuid;aid:=(p_input->>'actionId')::uuid;request:=(p_input->>'requestId')::uuid;
 if act not in('propose','accept','decline','withdraw') then raise exception 'Invalid action' using errcode='22023';end if;
 required:=case when act='propose' then array['action','requestId','id','actionId','requestRevision','start','durationMinutes','note'] else array['action','requestId','id','actionId','revision'] end;keys:=array(select jsonb_object_keys(p_input));
 if not(keys<@required and keys@>required) then raise exception 'Invalid fields' using errcode='22023';end if;
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id into owner from pro_appointment_requests where id=request and p_actor in(owner_id,client_user_id);if not found then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_appointment_reschedule_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.request_id<>request or prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
 select * into r from pro_appointment_requests where id=request for update;
 select * into w from pro_work where user_id=owner and id=r.work_id and "bookingClientId"=r.client_user_id::text for update;
 if w.id is null then raise exception 'Unavailable appointment' using errcode='42501';end if;
 if act in('propose','accept') and not pro_appointment_enabled(owner) then raise exception 'Provider unavailable' using errcode='42501';end if;
 if act='propose' then
  if p_actor<>owner then raise exception 'Only provider proposes' using errcode='42501';end if;
  if jsonb_typeof(p_input->'requestRevision') is distinct from 'number' or (p_input->>'requestRevision')!~'^[0-9]{1,9}$' or jsonb_typeof(p_input->'start') is distinct from 'string' or jsonb_typeof(p_input->'durationMinutes') is distinct from 'number' or (p_input->>'durationMinutes')!~'^[0-9]{1,3}$' or jsonb_typeof(p_input->'note') is distinct from 'string' or length(p_input->>'note')>500 then raise exception 'Invalid proposal' using errcode='22023';end if;
  if r.revision<>(p_input->>'requestRevision')::integer or r.status<>'confirmed' or w.cancelled or w.stage<>'scheduled' or pro_instant(w.start)<=now() then raise exception 'Appointment changed or started' using errcode='40001';end if;
  start_at:=pro_instant(p_input->>'start');duration:=(p_input->>'durationMinutes')::integer;
  if not pro_appointment_reschedule_slot_free(owner,w.id,start_at,duration) or start_at=pro_instant(w.start) and start_at+make_interval(mins=>duration)=pro_instant(w."end") then raise exception 'Unavailable or unchanged slot' using errcode='40001';end if;
  if (select count(*) from pro_appointment_reschedules where request_id=request)>=100 then raise exception 'History limit' using errcode='54000';end if;
  insert into pro_appointment_reschedules(id,request_id,owner_id,work_id,client_user_id,from_start,from_end,start_at,duration_minutes,note,request_revision) values(rid,request,owner,w.id,r.client_user_id,pro_instant(w.start),pro_instant(w."end"),start_at,duration,btrim(p_input->>'note'),r.revision) returning * into p;
 else
  if jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,9}$' then raise exception 'Invalid revision' using errcode='22023';end if;
  select * into p from pro_appointment_reschedules where id=rid and request_id=request for update;
  if not found then raise exception 'Unavailable proposal' using errcode='42501';end if;
  if p.status<>'proposed' or p.revision<>(p_input->>'revision')::integer then raise exception 'Proposal changed' using errcode='40001';end if;
  if act='withdraw' and p_actor<>owner or act in('accept','decline') and p_actor<>r.client_user_id then raise exception 'Forbidden action' using errcode='42501';end if;
  if act='accept' then
   if r.status<>'confirmed' or r.revision<>p.request_revision or w.cancelled or w.stage<>'scheduled' or pro_instant(w.start)<=now() or pro_instant(w.start) is distinct from p.from_start or pro_instant(w."end") is distinct from p.from_end then raise exception 'Appointment changed or started' using errcode='40001';end if;
   if not pro_appointment_reschedule_slot_free(owner,w.id,p.start_at,p.duration_minutes) then raise exception 'Slot unavailable' using errcode='40001';end if;
   prior_flag:=current_setting('contratacr.appointment_reschedule',true);perform set_config('contratacr.appointment_reschedule',p.id::text,true);
   update pro_work set start=pro_appointment_time(p.start_at),"end"=pro_appointment_time(p.start_at+make_interval(mins=>p.duration_minutes)) where user_id=owner and id=w.id;
   perform set_config('contratacr.appointment_reschedule',coalesce(prior_flag,''),true);
   update pro_appointment_requests set revision=revision+1,updated_at=now() where id=request returning * into r;
   update pro_workspace_core set revision=revision+1,updated_at=now() where user_id=owner;
   insert into pro_appointment_events(request_id,actor_id,side,action,note,start_at,end_at,status) values(request,p_actor,'client','reschedule',p.note,p.start_at,p.start_at+make_interval(mins=>p.duration_minutes),'confirmed');
  end if;
  update pro_appointment_reschedules set status=case when act='accept' then 'accepted' when act='decline' then 'declined' else 'withdrawn' end,revision=revision+1,updated_at=now() where id=p.id returning * into p;
 end if;
 result:=jsonb_build_object('id',p.id,'revision',p.revision,'status',p.status,'requestRevision',r.revision);
 insert into pro_appointment_reschedule_actions values(p_actor,aid,request,p_input,result);
 return result;
end $$;
create or replace function public.pro_appointment_reschedule_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if to_jsonb(new)-array['status','revision','updated_at'] is distinct from to_jsonb(old)-array['status','revision','updated_at'] or old.status<>'proposed' or new.status not in('accepted','declined','withdrawn') or new.revision<>old.revision+1 then raise exception 'Immutable reschedule proposal' using errcode='23514';end if;return new;
end $$;
drop trigger if exists pro_appointment_reschedule_immutable on pro_appointment_reschedules;
create trigger pro_appointment_reschedule_immutable before update on pro_appointment_reschedules for each row execute function pro_appointment_reschedule_immutable();
alter table pro_appointment_reschedules enable row level security;
alter table pro_appointment_reschedule_actions enable row level security;
revoke all on pro_appointment_reschedules,pro_appointment_reschedule_actions from public,anon,authenticated;
grant all on pro_appointment_reschedules,pro_appointment_reschedule_actions to service_role;
grant usage,select on sequence pro_appointment_reschedules_position_seq to service_role;
revoke all on function pro_appointment_reschedule_slot_free(uuid,text,timestamptz,integer),pro_appointment_reschedule_page(uuid,uuid,bigint),pro_appointment_reschedule_slots(uuid,uuid,date,integer),pro_appointment_reschedule_mutate(uuid,jsonb),pro_appointment_reschedule_immutable() from public,anon,authenticated;
grant execute on function pro_appointment_reschedule_slot_free(uuid,text,timestamptz,integer),pro_appointment_reschedule_page(uuid,uuid,bigint),pro_appointment_reschedule_slots(uuid,uuid,date,integer),pro_appointment_reschedule_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== appointment-opt-in-local.sql =====
-- LOCAL ONLY: explicit opt-in for NEW requests. Existing requests and work survive pausing.
begin;
create table if not exists public.pro_appointment_preferences (
 owner_id uuid primary key references profiles(id) on delete cascade,
 enabled boolean not null default false,revision integer not null check(revision>0),updated_at timestamptz not null default now()
);
create table if not exists public.pro_appointment_preference_actions (
 owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 primary key(owner_id,action_id)
);
create or replace function public.pro_appointment_preferences_record(p_actor uuid,p_input jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s pro_appointment_preferences;prior pro_appointment_preference_actions;result jsonb;aid uuid;
begin
 if not pro_appointment_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into s from pro_appointment_preferences where owner_id=p_actor;
 if p_input is not null then
  if jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['enabled','revision','actionId']) or (select count(*) from jsonb_object_keys(p_input))<>3 or jsonb_typeof(p_input->'enabled') is distinct from 'boolean' or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]+$' then raise exception 'Invalid preferences' using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;
  select * into prior from pro_appointment_preference_actions where owner_id=p_actor and action_id=aid;
  if found then if prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
  if (p_input->>'revision')::integer<>coalesce(s.revision,0) then raise exception 'Preferences changed' using errcode='40001';end if;
  insert into pro_appointment_preferences values(p_actor,(p_input->>'enabled')::boolean,coalesce(s.revision,0)+1,now()) on conflict(owner_id) do update set enabled=excluded.enabled,revision=excluded.revision,updated_at=excluded.updated_at returning * into s;
 end if;
 result:=jsonb_build_object('enabled',coalesce(s.enabled,false),'revision',coalesce(s.revision,0));
 if p_input is not null then insert into pro_appointment_preference_actions values(p_actor,aid,p_input,result);end if;
 return result;
end $$;
-- Patch the existing operation in place: check AFTER replay detection and under the SAME owner lock.
-- Fail loudly if a future operation changes the insertion point; never install an unguarded variant.
do $$
declare definition text;anchor text:='if act not in (''cancel'',''decline'') and not pro_appointment_enabled(owner) then';
begin
 definition:=pg_get_functiondef('public.pro_appointment_mutate(uuid,jsonb)'::regprocedure);
 if position('New requests are paused' in definition)=0 then
  if position(anchor in definition)=0 then raise exception 'Opt-in insertion point changed';end if;
  definition:=replace(definition,anchor,'if act=''create'' and not coalesce((select enabled from pro_appointment_preferences where owner_id=owner),false) then raise exception ''New requests are paused'' using errcode=''42501'';end if; '||anchor);
  execute definition;
 end if;
end $$;
alter table pro_appointment_preferences enable row level security;
alter table pro_appointment_preference_actions enable row level security;
revoke all on pro_appointment_preferences,pro_appointment_preference_actions from public,anon,authenticated;
grant all on pro_appointment_preferences,pro_appointment_preference_actions to service_role;
revoke all on function pro_appointment_preferences_record(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_appointment_preferences_record(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== appointment-schedule-local.sql =====
-- LOCAL ONLY. Weekly rules do not rewrite or materialize legacy availability/work.
begin;
create table if not exists public.pro_appointment_schedules(
 owner_id uuid primary key references profiles(id) on delete cascade,
 revision integer not null check(revision>0),duration_minutes integer not null check(duration_minutes between 15 and 480 and duration_minutes%15=0),
 weekly jsonb not null,closed_dates jsonb not null
);
create table if not exists public.pro_appointment_schedule_actions(
 owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,primary key(owner_id,action_id)
);
create or replace function public.pro_appointment_schedule_record(p_actor uuid,p_input jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s pro_appointment_schedules;prior pro_appointment_schedule_actions;result jsonb;b jsonb;d jsonb;aid uuid;
begin
 if not pro_appointment_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));select * into s from pro_appointment_schedules where owner_id=p_actor;
 if p_input is not null then
  if jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['revision','actionId','durationMinutes','weekly','closedDates']) or (select count(*) from jsonb_object_keys(p_input))<>5 or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]+$' or jsonb_typeof(p_input->'durationMinutes') is distinct from 'number' or (p_input->>'durationMinutes')!~'^[0-9]+$' or (p_input->>'durationMinutes')::integer not between 15 and 480 or (p_input->>'durationMinutes')::integer%15<>0 or jsonb_typeof(p_input->'weekly') is distinct from 'array' or jsonb_typeof(p_input->'closedDates') is distinct from 'array' then raise exception 'Invalid schedule' using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;select * into prior from pro_appointment_schedule_actions where owner_id=p_actor and action_id=aid;
  if found then if prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;return prior.result;end if;
  if (p_input->>'revision')::integer<>coalesce(s.revision,0) then raise exception 'Schedule changed' using errcode='40001';end if;
  if jsonb_array_length(p_input->'weekly')>28 or jsonb_array_length(p_input->'closedDates')>90 then raise exception 'Too many rules' using errcode='22023';end if;
  for b in select value from jsonb_array_elements(p_input->'weekly') loop
   if jsonb_typeof(b) is distinct from 'object' or not(b ?& array['weekday','start','end']) or (select count(*) from jsonb_object_keys(b))<>3 or jsonb_typeof(b->'weekday') is distinct from 'number' or (b->>'weekday')!~'^[1-7]$' or jsonb_typeof(b->'start') is distinct from 'string' or jsonb_typeof(b->'end') is distinct from 'string' or (b->>'start')!~'^([01][0-9]|2[0-3]):(00|15|30|45)$' or (b->>'end')!~'^([01][0-9]|2[0-3]):(00|15|30|45)$' or (b->>'end')<=(b->>'start') then raise exception 'Invalid weekly block' using errcode='22023';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p_input->'weekly') with ordinality a(v,n),jsonb_array_elements(p_input->'weekly') with ordinality b(v,n) where a.n<b.n and a.v->>'weekday'=b.v->>'weekday' and a.v->>'start'<b.v->>'end' and b.v->>'start'<a.v->>'end') then raise exception 'Overlapping hours' using errcode='22023';end if;
  for d in select value from jsonb_array_elements(p_input->'closedDates') loop
   if jsonb_typeof(d) is distinct from 'string' or (d#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char((d#>>'{}')::date,'YYYY-MM-DD')<>(d#>>'{}') then raise exception 'Invalid closed day' using errcode='22023';end if;
  end loop;
  if (select count(distinct value) from jsonb_array_elements(p_input->'closedDates'))<>jsonb_array_length(p_input->'closedDates') then raise exception 'Duplicate closed day' using errcode='22023';end if;
  insert into pro_appointment_schedules values(p_actor,coalesce(s.revision,0)+1,(p_input->>'durationMinutes')::integer,p_input->'weekly',p_input->'closedDates') on conflict(owner_id) do update set revision=excluded.revision,duration_minutes=excluded.duration_minutes,weekly=excluded.weekly,closed_dates=excluded.closed_dates returning * into s;
 end if;
 result:=jsonb_build_object('revision',coalesce(s.revision,0),'durationMinutes',coalesce(s.duration_minutes,60),'weekly',coalesce(s.weekly,'[]'),'closedDates',coalesce(s.closed_dates,'[]'));
 if p_input is not null then insert into pro_appointment_schedule_actions values(p_actor,aid,p_input,result);end if;return result;
end $$;
create or replace function public.pro_appointment_schedule_covers(p_owner uuid,p_start timestamptz,p_duration integer) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select not coalesce(s.closed_dates ? to_char(p_start at time zone 'America/Costa_Rica','YYYY-MM-DD'),false) and (
 exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>=p_start+make_interval(mins=>p_duration))
 or exists(select 1 from jsonb_array_elements(coalesce(s.weekly,'[]')) b where (b->>'weekday')::integer=extract(isodow from p_start at time zone 'America/Costa_Rica') and (p_start at time zone 'America/Costa_Rica')::time>=(b->>'start')::time and ((p_start+make_interval(mins=>p_duration)) at time zone 'America/Costa_Rica')::date=(p_start at time zone 'America/Costa_Rica')::date and ((p_start+make_interval(mins=>p_duration)) at time zone 'America/Costa_Rica')::time<=(b->>'end')::time))
 from (select 1) anchor left join pro_appointment_schedules s on s.owner_id=p_owner;
$$;
-- Public starts follow the owner's appointment length. Agreed rescheduling retains its flexibility.
create or replace function public.pro_appointment_schedule_start(p_owner uuid,p_start timestamptz) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select s.owner_id is null or exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>p_start and mod(extract(epoch from(p_start-pro_instant(a.start)))/60,s.duration_minutes)=0)
 or exists(select 1 from jsonb_array_elements(coalesce(s.weekly,'[]')) b where (b->>'weekday')::integer=extract(isodow from p_start at time zone 'America/Costa_Rica') and (p_start at time zone 'America/Costa_Rica')::time>=(b->>'start')::time and (p_start at time zone 'America/Costa_Rica')::time<(b->>'end')::time and mod(extract(epoch from((p_start at time zone 'America/Costa_Rica')::time-(b->>'start')::time))/60,s.duration_minutes)=0)
 from (select 1) anchor left join pro_appointment_schedules s on s.owner_id=p_owner;
$$;
revoke all on function pro_appointment_schedule_start(uuid,timestamptz) from public,anon,authenticated;
grant execute on function pro_appointment_schedule_start(uuid,timestamptz) to service_role;
do $$
declare definition text;anchor text:='where pro_appointment_slot_free(p_owner,t,p_duration)';
begin
 definition:=pg_get_functiondef('public.pro_appointment_slots(uuid,date,integer)'::regprocedure);
 if position('pro_appointment_schedule_start' in definition)=0 then
  if position(anchor in definition)=0 then raise exception 'Public slot grid changed';end if;
  execute replace(definition,anchor,anchor||' and pro_appointment_schedule_start(p_owner,t)');
 end if;
end $$;
-- Retain notice, buffer and conflict checks from the installed slot predicate.
do $$
declare definition text;signature text;anchor text:='exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>=p_start+make_interval(mins=>p_duration))';
begin
 foreach signature in array array['public.pro_appointment_slot_free(uuid,timestamptz,integer)','public.pro_appointment_reschedule_slot_free(uuid,text,timestamptz,integer)'] loop
  definition:=pg_get_functiondef(signature::regprocedure);
  if position('pro_appointment_schedule_covers' in definition)=0 then
   if position(anchor in definition)=0 then raise exception 'Slot predicate changed';end if;
   execute replace(definition,anchor,'pro_appointment_schedule_covers(p_owner,p_start,p_duration)');
  end if;
 end loop;
end $$;
-- Configuring a weekly schedule explicitly adopts direct reservations. Old requests stay unchanged.
-- Copy the established atomic work/contact creation block, without impersonating the owner.
do $$
declare definition text;anchor text:='event_side:=''client'';event_note:=r.note;';material text;
begin
 definition:=pg_get_functiondef('public.pro_appointment_mutate(uuid,jsonb)'::regprocedure);
 if position('-- weekly-direct-booking' in definition)=0 then
  if position(anchor in definition)=0 then raise exception 'Create insertion point changed';end if;
  material:=substring(definition from position('if (select count(*) from pro_work where user_id=owner)>=10000' in definition) for position('elsif act=''decline''' in definition)-position('if (select count(*) from pro_work where user_id=owner)>=10000' in definition));
  if material is null or position('r.work_id:=r.id::text;r.status:=''confirmed'';' in material)=0 then raise exception 'Work creation block changed';end if;
  execute replace(definition,anchor,anchor||'
  -- weekly-direct-booking
  if start_at is not null and exists(select 1 from pro_appointment_schedules where owner_id=owner) then
   if duration<>(select duration_minutes from pro_appointment_schedules where owner_id=owner) then raise exception ''Duration changed'' using errcode=''40001'';end if;
   if not exists(select 1 from pro_visit_preparation p cross join lateral jsonb_array_elements(p.questions) q where p.request_id=r.id and coalesce((q->>''required'')::boolean,false)) then
    '||material||'
    update pro_appointment_requests set work_id=r.work_id,status=r.status,updated_at=now() where id=r.id returning * into r;
   end if;
  end if;');
 end if;
end $$;
do $$
declare definition text;anchor text:='if duration<>(select duration_minutes from pro_appointment_schedules where owner_id=owner) then';
begin
 definition:=pg_get_functiondef('public.pro_appointment_mutate(uuid,jsonb)'::regprocedure);
 if position('pro_appointment_schedule_start(owner,start_at)' in definition)=0 then
  if position(anchor in definition)=0 then raise exception 'Direct duration guard changed';end if;
  execute replace(definition,anchor,'if duration<>(select duration_minutes from pro_appointment_schedules where owner_id=owner) or not pro_appointment_schedule_start(owner,start_at) then');
 end if;
end $$;
-- Retired direct endpoint cannot bypass weekly closures or the new request history.
do $$
declare definition text;anchor text:='select revision into v from pro_workspace_core where user_id=p_user for update;';
begin
 definition:=pg_get_functiondef('public.pro_reserve_core(uuid,jsonb,jsonb,integer)'::regprocedure);
 if position('Use the appointment calendar' in definition)=0 then
  if position(anchor in definition)=0 then raise exception 'Legacy booking guard changed';end if;
  execute replace(definition,anchor,'if exists(select 1 from pro_appointment_schedules where owner_id=p_user) then raise exception ''Use the appointment calendar'' using errcode=''40001'';end if; '||anchor);
 end if;
end $$;
create or replace function public.pro_appointment_calendar(p_owner uuid,p_month date,p_duration integer) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare d date;last_day date;result jsonb:='[]';slots jsonb;
begin
 if p_month is null or p_month<>date_trunc('month',p_month)::date or p_month<date_trunc('month',now() at time zone 'America/Costa_Rica')::date or p_month>date_trunc('month',(now() at time zone 'America/Costa_Rica')+interval '90 days')::date then raise exception 'Invalid month' using errcode='22023';end if;
 d:=greatest(p_month,(now() at time zone 'America/Costa_Rica')::date);last_day:=least((p_month+interval '1 month'-interval '1 day')::date,(now() at time zone 'America/Costa_Rica')::date+90);
 while d<=last_day loop
  slots:=pro_appointment_slots(p_owner,d,p_duration)->'slots';
  if jsonb_array_length(slots)>0 then result:=result||jsonb_build_array(jsonb_build_object('day',d,'count',jsonb_array_length(slots),'slots',(select jsonb_agg(v) from (select value v from jsonb_array_elements(slots) limit 3) x)));end if;
  d:=d+1;
 end loop;return result;
end $$;
revoke all on function pro_appointment_calendar(uuid,date,integer) from public,anon,authenticated;
grant execute on function pro_appointment_calendar(uuid,date,integer) to service_role;
alter table pro_appointment_schedules enable row level security;
alter table pro_appointment_schedule_actions enable row level security;
revoke all on pro_appointment_schedules,pro_appointment_schedule_actions from public,anon,authenticated;
grant all on pro_appointment_schedules,pro_appointment_schedule_actions to service_role;
revoke all on function pro_appointment_schedule_record(uuid,jsonb),pro_appointment_schedule_covers(uuid,timestamptz,integer) from public,anon,authenticated;
grant execute on function pro_appointment_schedule_record(uuid,jsonb),pro_appointment_schedule_covers(uuid,timestamptz,integer) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== appointment-list-local.sql =====
-- LOCAL PRO ONLY. Read-only combined list; existing records are not changed.
begin;
create or replace function public.pro_appointment_inbox(p_owner uuid,p_status text default 'pending',p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with entries as (
 select r.id::text id,'request'::text source,r.client_name client,r.service,
 coalesce(pro_instant(w.start),r.proposed_start,r.requested_start) start,
 coalesce(pro_instant(w.start),r.proposed_start,r.requested_start,r.created_at) at,
 case when w.cancelled or r.status in ('cancelled','declined') then 'cancelled' when w.stage='completed' or r.status='completed' then 'completed' when r.status in ('requested','proposed') then 'pending' else 'confirmed' end status,
 r.status detail_status
 from pro_appointment_requests r left join pro_work w on w.user_id=r.owner_id and w.id=r.work_id where r.owner_id=p_owner and r.origin='booking'
 union all
 select w.id,'manual',w.client,w.service,pro_instant(w.start),coalesce(pro_instant(w.start),'epoch'::timestamptz),
 -- Round 1 (2026-11-12): a job of the owner that is still new/quoting or has no dates is
 -- pending (to be scheduled), not confirmed; jobs linked by invitation are listed here too.
 case when w.cancelled then 'cancelled' when w.stage='completed' then 'completed' when w.stage in('new','quoting') or btrim(w.start)='' then 'pending' else 'confirmed' end,w.stage
 from pro_work w where w.user_id=p_owner and not exists(select 1 from pro_appointment_requests r where r.owner_id=p_owner and r.work_id=w.id and r.origin='booking')
 ), page as (
 select * from entries where (p_status='all' or status=p_status)
 and (p_after is null or (at,source,id)>((p_after->>'at')::timestamptz,p_after->>'source',p_after->>'id'))
 order by at,source,id limit 26
 ), visible as (select * from page order by at,source,id limit 25)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v)-'at' order by at,source,id) from visible v),'[]'::jsonb),
 'nextCursor',case when (select count(*) from page)>25 then (select jsonb_build_object('at',at,'source',source,'id',id) from visible order by at desc,source desc,id desc limit 1) else null end);
$$;
revoke all on function public.pro_appointment_inbox(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_appointment_inbox(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== request-quotes-local.sql =====
-- LOCAL PRO ONLY. Ordinary quote approval in the existing appointment journey.
-- Additive; no historical backfill, fiscal issuance, notifications or ledger entries.
-- An accepted linked document can supply the initial commercial balance on read.
begin;
create table if not exists public.pro_request_quotes(
 quote_id uuid primary key references public.quotes(id) on delete cascade,
 request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,
 owner_id uuid not null references public.profiles(id) on delete cascade,
 client_user_id uuid not null references public.profiles(id) on delete cascade,
 accepted boolean not null default false,created_at timestamptz not null default now(),check(owner_id<>client_user_id)
);
create unique index if not exists pro_request_quote_accepted_once on pro_request_quotes(request_id) where accepted;
create index if not exists pro_request_quote_client_page on pro_request_quotes(client_user_id,quote_id desc);
create table if not exists public.pro_request_quote_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,primary key(actor_id,action_id)
);

-- Shared by quote acceptance and appointment confirmation, in the same transaction.
create or replace function public.pro_request_quote_link_work(p_request uuid,p_quote uuid) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;w pro_work;q quotes;m pro_request_quotes;
begin
 select * into m from pro_request_quotes where request_id=p_request and quote_id=p_quote;
 if not found then raise exception 'Quote source unavailable' using errcode='P0002';end if;
 select * into r from pro_appointment_requests where id=p_request and owner_id=m.owner_id and client_user_id=m.client_user_id for update;
 if not found then raise exception 'Quote source changed' using errcode='40001';end if;
 if r.work_id is null then return;end if;
 select * into q from quotes where id=p_quote and client_id=r.client_user_id and professional_id=r.professional_id and status='accepted' and deleted_at is null;
 if not found then raise exception 'Accepted quote unavailable' using errcode='40001';end if;
 select * into w from pro_work where user_id=r.owner_id and id=r.work_id for update;
 if not found or r.status<>'confirmed' or w.cancelled or w.stage<>'scheduled' or w."clientId"<>'reservation-'||r.client_user_id::text or w."bookingClientId" is distinct from r.client_user_id::text then raise exception 'Work changed' using errcode='40001';end if;
 if w."externalQuoteId"=q.id::text then return;end if;
 if nullif(w."externalQuoteId",'') is not null or nullif(w."quoteId",'') is not null then raise exception 'Work already has a quote' using errcode='40001';end if;
 update pro_work set "externalQuoteId"=q.id::text where user_id=r.owner_id and id=r.work_id;
 update pro_workspace_core set revision=revision+1,updated_at=now() where user_id=r.owner_id;
end $$;

create or replace function public.pro_request_quote_sync() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare m pro_request_quotes;r pro_appointment_requests;
begin
 select * into m from pro_request_quotes where quote_id=new.id;
 if not found then return new;end if;
 -- Quote writes already use protected service-role APIs; authenticated has SELECT policies only.
 if current_setting('role',true) in ('anon','authenticated') then raise exception 'Use protected quote API' using errcode='42501';end if;
 select * into r from pro_appointment_requests where id=m.request_id;
 if new.client_id is distinct from m.client_user_id or new.professional_id is distinct from r.professional_id or new.project_id is not null then raise exception 'Quote source is immutable' using errcode='23514';end if;
 -- Preserve the accepted document used as the commercial agreement. Changes
 -- belong in the existing work-change workflow, never by rewriting its source.
 if m.accepted and (to_jsonb(new)-'updated_at') is distinct from (to_jsonb(old)-'updated_at') then raise exception 'Accepted request quote is immutable' using errcode='23514';end if;
 if new.status='accepted' and old.status is distinct from new.status then
  perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
  select * into r from pro_appointment_requests where id=m.request_id for update;
  if r.status not in ('requested','proposed','confirmed') then raise exception 'Request is closed' using errcode='40001';end if;
  update pro_request_quotes set accepted=true where quote_id=new.id;
  perform pro_request_quote_link_work(m.request_id,new.id);
 end if;
 return new;
end $$;
drop trigger if exists pro_request_quote_sync on public.quotes;
create trigger pro_request_quote_sync after update on public.quotes for each row execute function public.pro_request_quote_sync();
create or replace function public.pro_request_quote_confirm_work() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare selected_quote uuid;
begin
 if new.work_id is null or new.work_id is not distinct from old.work_id then return new;end if;
 select quote_id into selected_quote from pro_request_quotes where request_id=new.id and accepted;
 if selected_quote is not null then
  if current_setting('role',true) in ('anon','authenticated') then raise exception 'Use protected appointment API' using errcode='42501';end if;
  perform pro_request_quote_link_work(new.id,selected_quote);
 end if;
 return new;
end $$;
drop trigger if exists pro_request_quote_confirm_work on public.pro_appointment_requests;
create trigger pro_request_quote_confirm_work after update of work_id on public.pro_appointment_requests for each row execute function public.pro_request_quote_confirm_work();

create or replace function public.pro_request_quote_create(p_actor uuid,p_input jsonb,p_source jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;c pro_clients;prior pro_request_quote_actions;q quotes;totals jsonb;n integer;result jsonb;source uuid;aid uuid;
begin
 source:=(p_input->>'sourceRequestId')::uuid;aid:=(p_input->>'clientActionId')::uuid;
 if source is null or aid is null or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into prior from pro_request_quote_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Idempotency key changed' using errcode='22023';end if;return prior.result;end if;
 select * into r from pro_appointment_requests where id=source and owner_id=p_actor for update;
 if not found then raise exception 'Source unavailable' using errcode='P0002';end if;
 if not pro_appointment_enabled(p_actor) then raise exception 'Provider unavailable' using errcode='42501';end if;
 if r.status not in ('requested','proposed','confirmed') then raise exception 'Source closed' using errcode='40001';end if;
 if not exists(select 1 from profiles where id=r.client_user_id and not coalesce(is_disabled,false)) then raise exception 'Client unavailable' using errcode='42501';end if;
 select * into c from pro_clients where user_id=p_actor and id='reservation-'||r.client_user_id::text for update;
 if not found or c.archived then raise exception 'Prepare an active source contact first' using errcode='40001';end if;
 if jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items')<1 or jsonb_array_length(p_input->'items')>20 or p_input->>'taxMode' not in ('incluido','mas_iva','exento') or (p_input->>'validDays')::integer not between 1 and 90 then raise exception 'Invalid quote' using errcode='22023';end if;
 totals:=pro_quote_choice_totals(p_input->'items',p_input->>'taxMode');
 for attempt in 1..3 loop
  select coalesce(max(quote_number),0)+1 into n from quotes where professional_id=r.professional_id;
  begin
   insert into quotes(professional_id,client_id,client_name,client_phone,client_cedula,client_email,public_code,quote_number,title,items,tax_mode,subtotal,tax_amount,total,notes,valid_until,status,created_source_host,created_app_environment,created_supabase_project_ref)
   values(r.professional_id,r.client_user_id,coalesce(p_input->>'clientName',r.client_name),p_input->>'clientPhone',p_input->>'clientCedula',p_input->>'clientEmail',p_source->>'public_code',n,p_input->>'title',p_input->'items',p_input->>'taxMode',(totals->>'subtotal')::integer,(totals->>'taxAmount')::integer,(totals->>'total')::integer,p_input->>'notes',(now() at time zone 'America/Costa_Rica')::date+(p_input->>'validDays')::integer,'sent',p_source->>'created_source_host',p_source->>'created_app_environment',p_source->>'created_supabase_project_ref') returning * into q;
   exit;
  exception when unique_violation then if attempt=3 then raise;end if;
  end;
 end loop;
 insert into pro_request_quotes(quote_id,request_id,owner_id,client_user_id) values(q.id,r.id,r.owner_id,r.client_user_id);
 insert into pro_quote_links(user_id,"quoteId","clientId") values(p_actor,q.id::text,c.id);
 update pro_workspace_core set revision=revision+1,updated_at=now(),panel_fields=case when 'quoteLinks'=any(panel_fields) then panel_fields else array_append(panel_fields,'quoteLinks') end where user_id=p_actor;
 result:=jsonb_build_object('quote',to_jsonb(q),'sourceRequestId',r.id,'workId',r.work_id);
 insert into pro_request_quote_actions values(p_actor,aid,p_input,result);return result;
end $$;

create or replace function public.pro_request_quote_respond(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare m pro_request_quotes;prior pro_request_quote_actions;q quotes;result jsonb;act text;aid uuid;
begin
 act:=p_input->>'action';aid:=(p_input->>'clientActionId')::uuid;
 if aid is null or act not in ('accept','decline') then raise exception 'Invalid response' using errcode='22023';end if;
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into m from pro_request_quotes where quote_id=(p_input->>'id')::uuid and client_user_id=p_actor;
 if not found then raise exception 'Quote unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
 select * into prior from pro_request_quote_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Idempotency key changed' using errcode='22023';end if;return prior.result;end if;
 perform 1 from pro_appointment_requests where id=m.request_id for update;
 select * into q from quotes where id=m.quote_id and client_id=p_actor and deleted_at is null for update;
 if not found then raise exception 'Quote unavailable' using errcode='P0002';end if;
 if q.status<>'sent' or q.updated_at is distinct from (p_input->>'expectedUpdatedAt')::timestamptz or q.valid_until<(now() at time zone 'America/Costa_Rica')::date then raise exception 'Quote changed or expired' using errcode='40001';end if;
 if exists(select 1 from pro_quote_choices where quote_id=q.id) then raise exception 'Use extras approval' using errcode='40001';end if;
 if act='accept' and not pro_appointment_enabled(m.owner_id) then raise exception 'Provider unavailable' using errcode='42501';end if;
 update quotes set status=case when act='accept' then 'accepted' else 'declined' end,accepted_at=case when act='accept' then now() else null end,declined_at=case when act='decline' then now() else null end,updated_at=now() where id=q.id returning * into q;
 result:=jsonb_build_object('quote',to_jsonb(q),'sourceRequestId',m.request_id,'workId',(select work_id from pro_appointment_requests where id=m.request_id));
 insert into pro_request_quote_actions values(p_actor,aid,p_input,result);return result;
end $$;

create or replace function public.pro_request_quote_detail(p_actor uuid,p_quote uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('quote',to_jsonb(q),'sourceRequestId',m.request_id,'workId',r.work_id,'configuredExtras',exists(select 1 from pro_quote_choices where quote_id=q.id))
 from pro_request_quotes m join pro_appointment_requests r on r.id=m.request_id and r.owner_id=m.owner_id and r.client_user_id=m.client_user_id join quotes q on q.id=m.quote_id and q.professional_id=r.professional_id and q.client_id=m.client_user_id
 where q.id=p_quote and q.deleted_at is null and p_actor in(m.owner_id,m.client_user_id) and exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false));
$$;

-- One cursor and one list: extras keep their previous visibility; ordinary sources are exact request mappings.
create or replace function public.pro_quote_choice_page(p_actor uuid,p_after uuid default null,p_request uuid default null) returns jsonb language plpgsql stable set search_path=public,pg_temp as $$
declare result jsonb;next_key uuid;a pro_appointment_requests;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is not null then select * into a from pro_appointment_requests where id=p_request and p_actor in(owner_id,client_user_id);if not found then raise exception 'Forbidden' using errcode='42501';end if;end if;
 select coalesce(jsonb_agg(row order by id desc),'[]') into result from(
  select id,jsonb_build_object('quoteId',id,'title',title,'status',status,'version',version,'total',total,'professionalName',professional_name,'kind',kind) row from(
   select q.id,coalesce(q.title,'Cotización') title,case when q.status in ('withdrawn','declined') then q.status when c.status='open' and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then 'expired' else c.status end status,c.version,q.total,coalesce(p.business_name,'Profesional') professional_name,'extras'::text kind
   from pro_quote_choices c join quotes q on q.id=c.quote_id join professionals p on p.id=q.professional_id
   where q.deleted_at is null and (p_after is null or q.id<p_after) and (
    (p_request is null and c.client_id=p_actor) or
    (p_request is not null and c.owner_id=a.owner_id and c.client_id=a.client_user_id and (
     not exists(select 1 from pro_request_quotes mapped where mapped.quote_id=q.id) and exists(select 1 from pro_quote_links l join pro_work w on w.user_id=l.user_id and w."clientId"=l."clientId" where l.user_id=a.owner_id and l."quoteId"=q.id::text and w.id=a.work_id and w."bookingClientId"=a.client_user_id::text)
     or exists(select 1 from pro_request_quotes m where m.quote_id=q.id and m.request_id=p_request and m.owner_id=a.owner_id and m.client_user_id=a.client_user_id)
    ))
   )
   union all
   select q.id,coalesce(q.title,'Cotización'),case when q.status='sent' and q.valid_until<(now() at time zone 'America/Costa_Rica')::date then 'expired' when q.status='sent' then 'open' else q.status end,0,q.total,coalesce(p.business_name,'Profesional'),'ordinary'::text
   from pro_request_quotes m join pro_appointment_requests r on r.id=m.request_id and r.owner_id=m.owner_id and r.client_user_id=m.client_user_id join quotes q on q.id=m.quote_id and q.client_id=m.client_user_id and q.professional_id=r.professional_id join professionals p on p.id=q.professional_id
   where q.deleted_at is null and not exists(select 1 from pro_quote_choices where quote_id=q.id) and (p_after is null or q.id<p_after) and ((p_request is null and m.client_user_id=p_actor) or (p_request=m.request_id and p_actor in(m.owner_id,m.client_user_id)))
  ) combined order by id desc limit 21
 ) bounded;
 if jsonb_array_length(result)>20 then next_key:=(result->19->>'quoteId')::uuid;end if;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(result) with ordinality x(v,n) where n<=20),'nextCursor',next_key);
end $$;

alter table pro_request_quotes enable row level security;
alter table pro_request_quote_actions enable row level security;
revoke all on pro_request_quotes,pro_request_quote_actions from public,anon,authenticated;
grant all on pro_request_quotes,pro_request_quote_actions to service_role;
revoke all on function pro_request_quote_link_work(uuid,uuid),pro_request_quote_sync(),pro_request_quote_confirm_work(),pro_request_quote_create(uuid,jsonb,jsonb),pro_request_quote_respond(uuid,jsonb),pro_request_quote_detail(uuid,uuid),pro_quote_choice_page(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function pro_request_quote_link_work(uuid,uuid),pro_request_quote_sync(),pro_request_quote_confirm_work(),pro_request_quote_create(uuid,jsonb,jsonb),pro_request_quote_respond(uuid,jsonb),pro_request_quote_detail(uuid,uuid),pro_quote_choice_page(uuid,uuid,uuid) to service_role;

-- An accepted request quote supplies the initial commercial agreement only when
-- no manual agreement exists. Existing ledger entries, including zero, prevail.
create or replace function public.pro_work_account(p_user uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with account_values as (
 select w.*,
 coalesce(
  (select amount_cents from pro_client_entries where user_id=p_user and work_id=w.id and kind='agreement' order by position desc limit 1),
  -- Quotes are CRC documents with integer-colon totals. Derive cents exactly;
  -- this is a reading of the accepted document, never a charge or ledger entry.
  (select q.total::bigint*100
   from pro_request_quotes m
   join pro_appointment_requests r on r.id=m.request_id and r.owner_id=m.owner_id and r.client_user_id=m.client_user_id
   join quotes q on q.id=m.quote_id and q.client_id=m.client_user_id and q.professional_id=r.professional_id
   join professionals p on p.id=q.professional_id and p.profile_id=m.owner_id
   where m.owner_id=p_user and m.accepted and q.status='accepted' and q.deleted_at is null
    and r.work_id=w.id and w."externalQuoteId"=q.id::text and nullif(w."quoteId",'') is null
    and w."clientId"='reservation-'||r.client_user_id::text and w."bookingClientId"=r.client_user_id::text)
 ) as agreed,
 (select coalesce(sum(case when kind='payment' then amount_cents when kind='payment_void' then -amount_cents else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as paid,
 (select count(*) from pro_client_entries e where e.user_id=p_user and e.work_id=w.id and e.kind='material' and not exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id)) as materials,
 (select coalesce(sum(case when kind='material' then round(quantity*unit_cost,2) when kind='material_return' then -round(quantity*unit_cost,2) else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as material_cost
 from pro_work w where w.user_id=p_user and w.id=p_work
 ) select jsonb_build_object('id',id,'service',service,'stage',stage,'cancelled',cancelled,'start',start,'quoteId',"quoteId",'externalQuoteId',"externalQuoteId",'agreedCents',agreed,'paidCents',paid,'balanceCents',coalesce(agreed,0)-paid,'materialCount',materials,'materialCost',material_cost) from account_values;
$$;
revoke all on function public.pro_work_account(uuid,text) from public,anon,authenticated;
grant execute on function public.pro_work_account(uuid,text) to service_role;
commit;

-- ===== appointment-notifications-local.sql =====
-- LOCAL PRO ONLY. Opt-in internal appointment notices; never email or push delivery.
-- Empty rollout on installation. No historical events are scanned or backfilled.
begin;

-- Preserve every existing notification type; extend only this local installation.
do $$declare prior text;begin
 select pg_get_expr(conbin,conrelid) into prior from pg_constraint where conrelid='public.notifications'::regclass and conname='notifications_type_check' and contype='c';
 if prior is null then raise exception 'Notification type contract not found';end if;
 if position('pro_appointment_provider' in prior)=0 or position('pro_appointment_client' in prior)=0 then
  alter table public.notifications drop constraint notifications_type_check;
  execute format('alter table public.notifications add constraint notifications_type_check check ((%s) or type in (''pro_appointment_provider'',''pro_appointment_client''))',prior);
 end if;
end $$;

do $$begin
 if not exists(select 1 from pg_constraint where conrelid='public.notifications'::regclass and conname='pro_appointment_notification_data_check') then
  alter table public.notifications add constraint pro_appointment_notification_data_check check(
   type not in ('pro_appointment_provider','pro_appointment_client') or coalesce((
    data is not null and jsonb_typeof(data)='object' and data @> '{"version":1,"push_suppressed":true}'::jsonb
    and data ?& array['version','request_id','action','link','push_suppressed']
    and (data-array['version','request_id','action','link','push_suppressed'])='{}'::jsonb
    and jsonb_typeof(data->'request_id')='string' and (data->>'request_id')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and jsonb_typeof(data->'action')='string' and data->>'action' in ('requested','proposed','confirmed','declined','cancelled','completed','reschedule_proposed','reschedule_accepted','reschedule_declined','reschedule_withdrawn')
    and jsonb_typeof(data->'link')='string' and data->>'link'='/dashboard/profesional?tab='||case when type='pro_appointment_provider' then 'pro_agenda' else 'appointments' end||'&citaSolicitud='||(data->>'request_id')
   ),false)
  );
 end if;
end $$;
create table if not exists public.pro_appointment_notice_rollout(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 enabled boolean not null default false
);
create table if not exists public.pro_appointment_notice_receipts(
 source_kind text not null check(source_kind in ('appointment_event','reschedule_action')),
 source_key text not null check(length(source_key) between 1 and 100),
 recipient_id uuid not null references public.profiles(id) on delete cascade,
 request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,
 notification_id uuid references public.notifications(id) on delete set null,
 created_at timestamptz not null default now(),primary key(source_kind,source_key,recipient_id)
);

create or replace function public.pro_insert_appointment_notice(p_request uuid,p_actor uuid,p_source_kind text,p_source_key text,p_action text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;recipient uuid;notice_type text;notice_id uuid;
begin
 select * into r from pro_appointment_requests where id=p_request;
 if not found then raise exception 'Appointment notice source unavailable' using errcode='P0002';end if;
 if not exists(select 1 from pro_appointment_notice_rollout where owner_id=r.owner_id and enabled) then return;end if;
 if p_actor is null or p_actor not in (r.owner_id,r.client_user_id) then raise exception 'Invalid appointment notice actor' using errcode='42501';end if;
 if p_source_kind is null or p_action is null or p_source_kind not in ('appointment_event','reschedule_action') or p_source_key is null or length(p_source_key) not between 1 and 100 or p_action not in ('requested','proposed','confirmed','declined','cancelled','completed','reschedule_proposed','reschedule_accepted','reschedule_declined','reschedule_withdrawn') then raise exception 'Invalid appointment notice' using errcode='22023';end if;
 if p_source_kind='appointment_event' then
  if not exists(select 1 from pro_appointment_events e where e.request_id=p_request and e.actor_id=p_actor and e.position::text=p_source_key and p_action=case e.action when 'create' then case when e.status='confirmed' then 'confirmed' else 'requested' end when 'propose' then 'proposed' when 'confirm' then 'confirmed' when 'accept' then 'confirmed' when 'decline' then 'declined' when 'cancel' then 'cancelled' when 'complete' then 'completed' when 'completed' then 'completed' end) then raise exception 'Appointment notice event mismatch' using errcode='23514';end if;
 else
  if not exists(select 1 from pro_appointment_reschedule_actions a where a.request_id=p_request and a.actor_id=p_actor and a.actor_id::text||':'||a.action_id::text=p_source_key and p_action=case a.input->>'action' when 'propose' then 'reschedule_proposed' when 'accept' then 'reschedule_accepted' when 'decline' then 'reschedule_declined' when 'withdraw' then 'reschedule_withdrawn' end) then raise exception 'Appointment notice receipt mismatch' using errcode='23514';end if;
 end if;
 recipient:=case when p_actor=r.owner_id then r.client_user_id else r.owner_id end;
 if recipient=p_actor then raise exception 'Appointment notice must have a counterparty' using errcode='23514';end if;
 -- Disabled/deleted counterparties receive no new notices; this never blocks cancellation.
 if not exists(select 1 from profiles where id=recipient and not coalesce(is_disabled,false)) then return;end if;
 notice_type:=case when recipient=r.owner_id then 'pro_appointment_provider' else 'pro_appointment_client' end;
 -- Receipt survives dismissal. Reserve before insertion; any failure rolls back source + receipt + notice.
 insert into pro_appointment_notice_receipts(source_kind,source_key,recipient_id,request_id) values(p_source_kind,p_source_key,recipient,p_request) on conflict do nothing;
 if not found then return;end if;
 insert into notifications(user_id,type,title,message,data,read) values(recipient,notice_type,'Actualización de cita','Abre la cita para revisar la actualización.',jsonb_build_object('version',1,'request_id',p_request,'action',p_action,'link','/dashboard/profesional?tab='||case when recipient=r.owner_id then 'pro_agenda' else 'appointments' end||'&citaSolicitud='||p_request::text,'push_suppressed',true),false) returning id into notice_id;
 if notice_id is null then raise exception 'Appointment notice was not inserted' using errcode='23514';end if;
 update pro_appointment_notice_receipts set notification_id=notice_id where source_kind=p_source_kind and source_key=p_source_key and recipient_id=recipient;
end $$;

create or replace function public.pro_appointment_event_notice() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare normalized text;
begin
 normalized:=case new.action when 'create' then case when new.status='confirmed' then 'confirmed' else 'requested' end when 'propose' then 'proposed' when 'confirm' then 'confirmed' when 'accept' then 'confirmed' when 'decline' then 'declined' when 'cancel' then 'cancelled' when 'complete' then 'completed' when 'completed' then 'completed' end;
 -- Accepted rescheduling is notified from its durable action receipt, once only.
 if normalized is not null then perform pro_insert_appointment_notice(new.request_id,new.actor_id,'appointment_event',new.position::text,normalized);end if;
 return new;
end $$;
create or replace function public.pro_appointment_reschedule_notice() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare normalized text;
begin
 normalized:=case new.input->>'action' when 'propose' then 'reschedule_proposed' when 'accept' then 'reschedule_accepted' when 'decline' then 'reschedule_declined' when 'withdraw' then 'reschedule_withdrawn' end;
 if normalized is null then raise exception 'Invalid reschedule receipt' using errcode='22023';end if;
 perform pro_insert_appointment_notice(new.request_id,new.actor_id,'reschedule_action',new.actor_id::text||':'||new.action_id::text,normalized);
 return new;
end $$;
drop trigger if exists pro_appointment_event_notice on public.pro_appointment_events;
create trigger pro_appointment_event_notice after insert on public.pro_appointment_events for each row execute function public.pro_appointment_event_notice();
drop trigger if exists pro_appointment_reschedule_notice on public.pro_appointment_reschedule_actions;
create trigger pro_appointment_reschedule_notice after insert on public.pro_appointment_reschedule_actions for each row execute function public.pro_appointment_reschedule_notice();

alter table pro_appointment_notice_rollout enable row level security;
alter table pro_appointment_notice_receipts enable row level security;
revoke all on pro_appointment_notice_rollout,pro_appointment_notice_receipts from public,anon,authenticated;
grant all on pro_appointment_notice_rollout,pro_appointment_notice_receipts to service_role;
revoke all on function pro_insert_appointment_notice(uuid,uuid,text,text,text),pro_appointment_event_notice(),pro_appointment_reschedule_notice() from public,anon,authenticated;
grant execute on function pro_insert_appointment_notice(uuid,uuid,text,text,text),pro_appointment_event_notice(),pro_appointment_reschedule_notice() to service_role;
notify pgrst,'reload schema';
commit;

-- ===== appointment-reminders-local.sql =====
-- LOCAL PRO ONLY. Personal 24-hour in-app reminders. No scheduler, push or email.
-- Additive and opt-in: empty rollout/preferences; no historical backfill or data deletion.
begin;
create table if not exists public.pro_appointment_reminder_rollout(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 enabled boolean not null default false,enabled_since timestamptz,
 check(enabled=(enabled_since is not null))
);
create or replace function public.pro_appointment_reminder_rollout_time() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if not new.enabled then new.enabled_since:=null;
 elsif tg_op='INSERT' then new.enabled_since:=clock_timestamp();
 elsif not old.enabled then new.enabled_since:=clock_timestamp();
 else new.enabled_since:=old.enabled_since;end if;
 return new;
end $$;
drop trigger if exists pro_appointment_reminder_rollout_time on public.pro_appointment_reminder_rollout;
create trigger pro_appointment_reminder_rollout_time before insert or update on public.pro_appointment_reminder_rollout for each row execute function public.pro_appointment_reminder_rollout_time();
create table if not exists public.pro_appointment_reminder_preferences(
 user_id uuid primary key references public.profiles(id) on delete cascade,
 enabled boolean not null default false,revision integer not null check(revision>0),
 enabled_since timestamptz,updated_at timestamptz not null default now(),
 check(enabled=(enabled_since is not null))
);
create table if not exists public.pro_appointment_reminder_preference_actions(
 user_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,primary key(user_id,action_id)
);
create table if not exists public.pro_appointment_reminder_receipts(
 request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,
 scheduled_start timestamptz not null,scheduled_end timestamptz not null check(scheduled_end>scheduled_start),
 lead_minutes integer not null default 1440 check(lead_minutes=1440),
 recipient_id uuid not null references public.profiles(id) on delete cascade,
 owner_id uuid not null references public.profiles(id) on delete cascade,
 source_event_position bigint not null references public.pro_appointment_events(position),
 notification_id uuid references public.notifications(id) on delete set null,
 evaluated_as_of timestamptz not null,created_at timestamptz not null default now(),
 invalidated_at timestamptz,invalidation_reason text check(invalidation_reason in ('cancelled','completed','rescheduled','source_changed')),
 primary key(request_id,scheduled_start,lead_minutes,recipient_id),
 check((invalidated_at is null)=(invalidation_reason is null))
);
create index if not exists pro_appointment_reminder_open on public.pro_appointment_reminder_receipts(request_id) where invalidated_at is null;

do $$declare prior text;begin
 select pg_get_expr(conbin,conrelid) into prior from pg_constraint where conrelid='public.notifications'::regclass and conname='notifications_type_check' and contype='c';
 if prior is null then raise exception 'Notification type contract not found';end if;
 if position('pro_appointment_reminder_provider' in prior)=0 or position('pro_appointment_reminder_client' in prior)=0 then
  alter table public.notifications drop constraint notifications_type_check;
  execute format('alter table public.notifications add constraint notifications_type_check check ((%s) or type in (''pro_appointment_reminder_provider'',''pro_appointment_reminder_client''))',prior);
 end if;
 if not exists(select 1 from pg_constraint where conrelid='public.notifications'::regclass and conname='pro_appointment_reminder_data_check') then
  alter table public.notifications add constraint pro_appointment_reminder_data_check check(
   type not in ('pro_appointment_reminder_provider','pro_appointment_reminder_client') or coalesce((
    data is not null and jsonb_typeof(data)='object' and data @> '{"version":1,"action":"reminder_24h","push_suppressed":true}'::jsonb
    and data ?& array['version','request_id','action','invalidated','link','push_suppressed']
    and (data-array['version','request_id','action','invalidated','link','push_suppressed'])='{}'::jsonb
    and jsonb_typeof(data->'request_id')='string' and (data->>'request_id')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and jsonb_typeof(data->'invalidated')='boolean'
    and jsonb_typeof(data->'link')='string' and data->>'link'='/dashboard/profesional?tab='||case when type='pro_appointment_reminder_provider' then 'pro_agenda' else 'appointments' end||'&citaSolicitud='||(data->>'request_id')
   ),false)
  );
 end if;
end $$;

create or replace function public.pro_appointment_reminder_available(p_actor uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(
  select 1 from pro_appointment_reminder_rollout x join profiles p on p.id=x.owner_id and not coalesce(p.is_disabled,false)
  join professionals professional on professional.profile_id=x.owner_id and not coalesce(professional.is_banned,false)
  where x.enabled and (x.owner_id=p_actor or exists(select 1 from pro_appointment_requests r where r.owner_id=x.owner_id and r.client_user_id=p_actor))
 );
$$;
create or replace function public.pro_appointment_reminder_preferences_record(p_actor uuid,p_input jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s pro_appointment_reminder_preferences;prior pro_appointment_reminder_preference_actions;aid uuid;available boolean;result jsonb;
begin
 if p_actor is null or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 available:=pro_appointment_reminder_available(p_actor);
 if p_input is not null then
  if jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['enabled','expectedRevision','actionId']) or (p_input-array['enabled','expectedRevision','actionId'])<>'{}'::jsonb
   or jsonb_typeof(p_input->'enabled') is distinct from 'boolean' or jsonb_typeof(p_input->'expectedRevision') is distinct from 'number' or (p_input->>'expectedRevision')!~'^[0-9]{1,9}$' then raise exception 'Invalid reminder preference' using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;if aid is null then raise exception 'Missing action identity' using errcode='22023';end if;
  select * into prior from pro_appointment_reminder_preference_actions where user_id=p_actor and action_id=aid;
  if found then
   if prior.input is distinct from p_input then raise exception 'Changed retry' using errcode='22023';end if;
   return prior.result||jsonb_build_object('available',available);
  end if;
 end if;
 select * into s from pro_appointment_reminder_preferences where user_id=p_actor for update;
 if p_input is not null then
  if (p_input->>'expectedRevision')::integer<>coalesce(s.revision,0) then raise exception 'Reminder preference changed' using errcode='40001';end if;
  if (p_input->>'enabled')::boolean and not available then raise exception 'Reminders are not enabled here' using errcode='42501';end if;
  insert into pro_appointment_reminder_preferences(user_id,enabled,revision,enabled_since)
  values(p_actor,(p_input->>'enabled')::boolean,coalesce(s.revision,0)+1,case when (p_input->>'enabled')::boolean then coalesce(s.enabled_since,clock_timestamp()) end)
  on conflict(user_id) do update set enabled=excluded.enabled,revision=excluded.revision,enabled_since=excluded.enabled_since,updated_at=now() returning * into s;
 end if;
 result:=jsonb_build_object('enabled',coalesce(s.enabled,false),'revision',coalesce(s.revision,0),'available',available);
 if p_input is not null then insert into pro_appointment_reminder_preference_actions values(p_actor,aid,p_input,result);end if;
 return result;
end $$;

-- Select current confirmed timing only, never a pending proposal/requested_start.
-- Exclude durable receipts before LIMIT so earlier emitted rows cannot starve others.
create or replace function public.pro_appointment_reminder_due(p_as_of timestamptz,p_request uuid default null,p_recipient uuid default null)
returns table(request_id uuid,recipient_id uuid,owner_id uuid,scheduled_start timestamptz,scheduled_end timestamptz,source_event_position bigint,due_at timestamptz)
language sql stable security invoker set search_path=public,pg_temp as $$
 select r.id,recipient.id,r.owner_id,pro_instant(w.start),pro_instant(w."end"),e.position,pro_instant(w.start)-interval '24 hours'
 from pro_appointment_requests r
 join pro_work w on w.user_id=r.owner_id and w.id=r.work_id and w."bookingClientId"=r.client_user_id::text and w."clientId"='reservation-'||r.client_user_id::text
 join professionals professional on professional.id=r.professional_id and professional.profile_id=r.owner_id and not coalesce(professional.is_banned,false)
 join profiles owner on owner.id=r.owner_id and not coalesce(owner.is_disabled,false)
 join pro_appointment_reminder_rollout rollout on rollout.owner_id=r.owner_id and rollout.enabled
 cross join lateral(values(r.owner_id),(r.client_user_id)) recipient(id)
 join profiles actor on actor.id=recipient.id and not coalesce(actor.is_disabled,false)
 join pro_appointment_reminder_preferences pref on pref.user_id=recipient.id and pref.enabled
 join lateral(select event.position,event.at from pro_appointment_events event where event.request_id=r.id and event.status='confirmed'
  and event.action in ('create','confirm','accept','reschedule') and event.start_at=pro_instant(w.start) and event.end_at=pro_instant(w."end") order by event.position desc limit 1)e on true
 where r.status='confirmed' and w.stage='scheduled' and not w.cancelled and pro_instant(w.start)>p_as_of
  and pro_instant(w.start)-interval '24 hours'<=p_as_of and p_as_of<pro_instant(w.start)-interval '24 hours'+interval '15 minutes'
  and e.at<=pro_instant(w.start)-interval '24 hours' and pref.enabled_since<=pro_instant(w.start)-interval '24 hours' and rollout.enabled_since<=pro_instant(w.start)-interval '24 hours'
  and (p_request is null or r.id=p_request) and (p_recipient is null or recipient.id=p_recipient)
  and not exists(select 1 from pro_appointment_reminder_receipts sent where sent.request_id=r.id and sent.scheduled_start=pro_instant(w.start) and sent.lead_minutes=1440 and sent.recipient_id=recipient.id);
$$;

create or replace function public.pro_appointment_reminder_invalidate(p_request uuid) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;w pro_work;owner uuid;source bigint;entry pro_appointment_reminder_receipts;reason text;n integer:=0;
begin
 if not exists(select 1 from pro_appointment_reminder_receipts where request_id=p_request and invalidated_at is null) then return 0;end if;
 select owner_id into owner from pro_appointment_requests where id=p_request;if owner is null then return 0;end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into r from pro_appointment_requests where id=p_request for update;
 select * into w from pro_work where user_id=r.owner_id and id=r.work_id for update;
 select e.position into source from pro_appointment_events e where e.request_id=r.id and e.status='confirmed' and e.action in ('create','confirm','accept','reschedule') and e.start_at=pro_instant(w.start) and e.end_at=pro_instant(w."end") order by e.position desc limit 1;
 for entry in select * from pro_appointment_reminder_receipts where request_id=r.id and invalidated_at is null for update loop
  reason:=case when r.status='cancelled' or w.cancelled then 'cancelled' when r.status='completed' or w.stage='completed' then 'completed'
   when w.id is null or r.status<>'confirmed' or w.stage<>'scheduled' or w."bookingClientId" is distinct from r.client_user_id::text or w."clientId" is distinct from 'reservation-'||r.client_user_id::text then 'source_changed'
   when entry.scheduled_start is distinct from pro_instant(w.start) or entry.scheduled_end is distinct from pro_instant(w."end") then 'rescheduled'
   when source is distinct from entry.source_event_position then 'source_changed' end;
  if reason is not null then
   update pro_appointment_reminder_receipts set invalidated_at=clock_timestamp(),invalidation_reason=reason where request_id=entry.request_id and scheduled_start=entry.scheduled_start and lead_minutes=entry.lead_minutes and recipient_id=entry.recipient_id;
   -- Keep the notification's read state, original payload and history. No deletion.
   update notifications set data=jsonb_set(data,'{invalidated}','true'::jsonb) where id=entry.notification_id and user_id=entry.recipient_id and type in ('pro_appointment_reminder_provider','pro_appointment_reminder_client');
   n:=n+1;
  end if;
 end loop;
 return n;
end $$;
create or replace function public.pro_appointment_reminder_source_changed() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare request uuid;
begin
 if tg_table_name='pro_appointment_requests' then request:=new.id;
 elsif tg_table_name='pro_appointment_events' then request:=new.request_id;
 else select id into request from pro_appointment_requests where owner_id=new.user_id and work_id=new.id;end if;
 if request is not null then perform pro_appointment_reminder_invalidate(request);end if;
 return new;
end $$;
drop trigger if exists pro_appointment_reminder_request_changed on public.pro_appointment_requests;
create trigger pro_appointment_reminder_request_changed after update on public.pro_appointment_requests for each row execute function public.pro_appointment_reminder_source_changed();
drop trigger if exists pro_appointment_reminder_work_changed on public.pro_work;
create trigger pro_appointment_reminder_work_changed after update on public.pro_work for each row execute function public.pro_appointment_reminder_source_changed();
drop trigger if exists pro_appointment_reminder_event_changed on public.pro_appointment_events;
create trigger pro_appointment_reminder_event_changed after insert on public.pro_appointment_events for each row execute function public.pro_appointment_reminder_source_changed();

create or replace function public.pro_appointment_reminders_run(p_as_of timestamptz default now(),p_limit integer default 100) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare candidate record;current_source record;batch jsonb;lock_owner uuid;lock_profile uuid;lock_professional uuid;notice uuid;notice_type text;created integer:=0;invalidated integer:=0;
begin
 if p_as_of is null or not isfinite(p_as_of) or p_limit is null or p_limit<1 or p_limit>500 then raise exception 'Invalid reminder run' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(d) order by d.due_at,d.request_id,d.recipient_id),'[]'::jsonb) into batch from (
  select * from pro_appointment_reminder_due(p_as_of) order by due_at,request_id,recipient_id limit p_limit
 )d;
 -- Moderation updates these rows without owner advisory locks. Lock identities
 -- first, before owner/appointment locks, then revalidate the candidate below.
 for lock_profile in select id from (
  select (value->>'owner_id')::uuid id from jsonb_array_elements(batch)
  union select (value->>'recipient_id')::uuid id from jsonb_array_elements(batch)
 )identities order by id loop
  perform 1 from profiles where id=lock_profile for share;
 end loop;
 for lock_professional in select distinct r.professional_id from pro_appointment_requests r
  join jsonb_array_elements(batch)b on (b.value->>'request_id')::uuid=r.id order by r.professional_id loop
  perform 1 from professionals where id=lock_professional for share;
 end loop;
 -- Acquire all owner locks first in a stable order. A recipient may also be an
 -- owner: never take their advisory lock after retaining a preference row lock.
 for lock_owner in select distinct (value->>'owner_id')::uuid from jsonb_array_elements(batch) order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended(lock_owner::text,0));
 end loop;
 for candidate in select * from jsonb_to_recordset(batch) as x(request_id uuid,recipient_id uuid,owner_id uuid) loop
  -- Same ordering as appointment writers: owner advisory before request/work.
  perform 1 from pro_appointment_requests where id=candidate.request_id for update skip locked;
  if not found then continue;end if;
  perform 1 from pro_work where user_id=candidate.owner_id and id=(select work_id from pro_appointment_requests where id=candidate.request_id) for update skip locked;
  if not found then continue;end if;
  perform 1 from pro_appointment_reminder_rollout where owner_id=candidate.owner_id for share;
  perform 1 from pro_appointment_reminder_preferences where user_id=candidate.recipient_id for share;
  invalidated:=invalidated+pro_appointment_reminder_invalidate(candidate.request_id);
  select * into current_source from pro_appointment_reminder_due(p_as_of,candidate.request_id,candidate.recipient_id);
  if not found then continue;end if;
  insert into pro_appointment_reminder_receipts(request_id,scheduled_start,scheduled_end,recipient_id,owner_id,source_event_position,evaluated_as_of)
  values(current_source.request_id,current_source.scheduled_start,current_source.scheduled_end,current_source.recipient_id,current_source.owner_id,current_source.source_event_position,p_as_of) on conflict do nothing;
  if not found then continue;end if;
  notice_type:=case when current_source.recipient_id=current_source.owner_id then 'pro_appointment_reminder_provider' else 'pro_appointment_reminder_client' end;
  insert into notifications(user_id,type,title,message,data,read) values(current_source.recipient_id,notice_type,'Recordatorio de cita','Consulte la fecha y hora actuales de su cita.',jsonb_build_object('version',1,'request_id',current_source.request_id,'action','reminder_24h','invalidated',false,'link','/dashboard/profesional?tab='||case when current_source.recipient_id=current_source.owner_id then 'pro_agenda' else 'appointments' end||'&citaSolicitud='||current_source.request_id::text,'push_suppressed',true),false) returning id into notice;
  if notice is null then raise exception 'Reminder notice not inserted' using errcode='23514';end if;
  update pro_appointment_reminder_receipts set notification_id=notice where request_id=current_source.request_id and scheduled_start=current_source.scheduled_start and lead_minutes=1440 and recipient_id=current_source.recipient_id;
  created:=created+1;
 end loop;
 return jsonb_build_object('created',created,'invalidated',invalidated,'hasMore',exists(select 1 from pro_appointment_reminder_due(p_as_of)));
end $$;

do $$declare name text;begin foreach name in array array['pro_appointment_reminder_rollout','pro_appointment_reminder_preferences','pro_appointment_reminder_preference_actions','pro_appointment_reminder_receipts'] loop
 execute format('alter table public.%I enable row level security',name);
 execute format('revoke all on public.%I from public,anon,authenticated',name);
 execute format('grant all on public.%I to service_role',name);
end loop;end $$;
revoke all on function pro_appointment_reminder_rollout_time(),pro_appointment_reminder_available(uuid),pro_appointment_reminder_preferences_record(uuid,jsonb),pro_appointment_reminder_due(timestamptz,uuid,uuid),pro_appointment_reminder_invalidate(uuid),pro_appointment_reminder_source_changed(),pro_appointment_reminders_run(timestamptz,integer) from public,anon,authenticated;
grant execute on function pro_appointment_reminder_rollout_time(),pro_appointment_reminder_available(uuid),pro_appointment_reminder_preferences_record(uuid,jsonb),pro_appointment_reminder_due(timestamptz,uuid,uuid),pro_appointment_reminder_invalidate(uuid),pro_appointment_reminder_source_changed(),pro_appointment_reminders_run(timestamptz,integer) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== direct-project-quotes-local.sql =====
-- LOCAL PRO ONLY. Additive creation receipts; no backfill, delivery, invoices or debt.
begin;
create table if not exists public.pro_direct_project_quote_actions(
 actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,primary key(actor_id,action_id)
);
create or replace function public.pro_direct_project_quote_create(p_actor uuid,p_input jsonb,p_source jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c pro_clients;prior pro_direct_project_quote_actions;q quotes;totals jsonb;n integer;result jsonb;aid uuid;professional professionals;project projects;recipient uuid;item jsonb;field text;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or (p_input-array['context','clientActionId','proClientId','projectId','clientName','clientPhone','clientCedula','clientEmail','title','items','taxMode','notes','validDays'])<>'{}'::jsonb
 or not(p_input ?& array['context','clientActionId','proClientId','clientName','clientPhone','clientCedula','clientEmail','title','items','taxMode','notes','validDays'])
 or p_input->>'context' not in ('direct','project') or jsonb_typeof(p_input->'context') is distinct from 'string'
 or jsonb_typeof(p_input->'proClientId') not in ('string','null') or jsonb_typeof(p_input->'proClientId')='string' and length(p_input->>'proClientId') not between 1 and 160
 or (p_input->>'context'='project') is distinct from (p_input ? 'projectId') then raise exception 'Invalid context' using errcode='22023';end if;
 aid:=(p_input->>'clientActionId')::uuid;
 if aid is null or p_actor is null then raise exception 'Missing actor or action' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 if not pro_appointment_enabled(p_actor) then raise exception 'Provider unavailable' using errcode='42501';end if;
 select * into professional from professionals where profile_id=p_actor and not coalesce(is_banned,false) order by id limit 1;
 if not found then raise exception 'Provider unavailable' using errcode='42501';end if;
 select * into prior from pro_direct_project_quote_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Idempotency key changed' using errcode='22023';end if;return prior.result;end if;
 if p_input->>'proClientId' is not null then
 select * into c from pro_clients where user_id=p_actor and id=p_input->>'proClientId' for update;
 if not found or c.archived then raise exception 'Active contact required' using errcode='40001';end if;
 end if;
 if p_input->>'context'='project' then
  select * into project from projects where id=(p_input->>'projectId')::uuid for share;
  if not found then raise exception 'Project unavailable' using errcode='P0002';end if;
  if project.client_id=p_actor then raise exception 'Own project' using errcode='42501';end if;
  if project.status<>'open' or not coalesce(project.allow_direct_contact,false) or project.client_id is null then raise exception 'Project unavailable' using errcode='40001';end if;
  if c.id is null or c.id<>'reservation-'||project.client_id::text or not exists(select 1 from profiles where id=project.client_id and not coalesce(is_disabled,false)) then raise exception 'Project recipient mismatch' using errcode='42501';end if;
  recipient:=project.client_id;
 end if;
 if p_input->>'context'='direct' and length(btrim(coalesce(p_input->>'clientName','')))=0 then raise exception 'Client name required' using errcode='22023';end if;
 foreach field in array array['clientName','clientPhone','clientCedula','clientEmail','title','notes'] loop
  if jsonb_typeof(p_input->field) not in ('string','null') or length(p_input->>field)>(case field when 'notes' then 3000 when 'clientEmail' then 254 when 'clientPhone' then 40 when 'clientCedula' then 40 else 160 end) then raise exception 'Invalid text' using errcode='22023';end if;
 end loop;
 if jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items') not between 1 and 20
 or p_input->>'taxMode' not in ('incluido','mas_iva','exento') or jsonb_typeof(p_input->'validDays') is distinct from 'number' or (p_input->>'validDays')!~'^[0-9]{1,2}$' or (p_input->>'validDays')::integer not between 1 and 90 then raise exception 'Invalid quote' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_input->'items') loop
  if jsonb_typeof(item) is distinct from 'object' or not(item ?& array['description','quantity','unit_price']) or (item-array['description','quantity','unit_price'])<>'{}'::jsonb or jsonb_typeof(item->'description') is distinct from 'string' or length(btrim(item->>'description')) not between 1 and 500
   or jsonb_typeof(item->'quantity') is distinct from 'number' or jsonb_typeof(item->'unit_price') is distinct from 'number' then raise exception 'Invalid line' using errcode='22023';end if;
  if (item->>'quantity')::numeric<=0 or (item->>'quantity')::numeric>9999 or trunc((item->>'quantity')::numeric,2)<>(item->>'quantity')::numeric or (item->>'unit_price')::numeric<0 or (item->>'unit_price')::numeric>222222222 or trunc((item->>'unit_price')::numeric)<>(item->>'unit_price')::numeric then raise exception 'Invalid amount' using errcode='22023';end if;
 end loop;
 totals:=pro_quote_choice_totals(p_input->'items',p_input->>'taxMode');
 for attempt in 1..3 loop
  select coalesce(max(quote_number),0)+1 into n from quotes where professional_id=professional.id;
  begin
   insert into quotes(professional_id,project_id,client_id,client_name,client_phone,client_cedula,client_email,public_code,quote_number,title,items,tax_mode,subtotal,tax_amount,total,notes,valid_until,status,created_source_host,created_app_environment,created_supabase_project_ref)
   values(professional.id,project.id,recipient,p_input->>'clientName',p_input->>'clientPhone',p_input->>'clientCedula',p_input->>'clientEmail',p_source->>'public_code',n,p_input->>'title',p_input->'items',p_input->>'taxMode',(totals->>'subtotal')::integer,(totals->>'taxAmount')::integer,(totals->>'total')::integer,p_input->>'notes',(now() at time zone 'America/Costa_Rica')::date+(p_input->>'validDays')::integer,'sent',p_source->>'created_source_host',p_source->>'created_app_environment',p_source->>'created_supabase_project_ref') returning * into q;
   exit;
  exception when unique_violation then if attempt=3 then raise;end if;
  end;
 end loop;
 if c.id is not null then insert into pro_quote_links(user_id,"quoteId","clientId") values(p_actor,q.id::text,c.id);end if;
 update pro_workspace_core set revision=revision+1,updated_at=now(),panel_fields=case when 'quoteLinks'=any(panel_fields) then panel_fields else array_append(panel_fields,'quoteLinks') end where user_id=p_actor;
 result:=jsonb_build_object('quote',to_jsonb(q)||jsonb_build_object('professional_name',professional.business_name,'professional_full_name',(select full_name from profiles where id=p_actor)));
 insert into pro_direct_project_quote_actions values(p_actor,aid,p_input,result);return result;
end $$;

alter table pro_direct_project_quote_actions enable row level security;
revoke all on pro_direct_project_quote_actions from public,anon,authenticated;
grant all on pro_direct_project_quote_actions to service_role;
revoke all on function public.pro_direct_project_quote_create(uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.pro_direct_project_quote_create(uuid,jsonb,jsonb) to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== client-write-recovery-local.sql =====
-- LOCAL PRO ONLY. Additive, opt-in receipts for one customer create/edit form.
-- No backfill or changes to the existing catalog/import/stock mutation contract.
begin;
create table if not exists public.pro_client_write_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input jsonb not null,result jsonb not null,
 primary key(actor_id,action_id)
);
alter table public.pro_client_write_actions enable row level security;
revoke all on public.pro_client_write_actions from public,anon,authenticated;
grant all on public.pro_client_write_actions to service_role;
create or replace function public.pro_client_write_record(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior pro_client_write_actions;aid uuid;r jsonb;field text;v integer;result jsonb;mode text;
begin
 if p_actor is null then raise exception 'Missing actor' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object'
 or (p_input-array['kind','revision','rows','movements','importing','clientActionId','clientWriteMode'])<>'{}'::jsonb
 or not(p_input ?& array['kind','revision','rows','movements','importing','clientActionId','clientWriteMode'])
 or p_input->'kind' is distinct from '"clients"'::jsonb or p_input->'importing' is distinct from 'false'::jsonb
 or p_input->'movements' is distinct from '[]'::jsonb
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,10}$'
 or jsonb_typeof(p_input->'rows') is distinct from 'array' then raise exception 'Invalid customer write' using errcode='22023';end if;
 if (p_input->>'revision')::bigint>2147483646 or jsonb_array_length(p_input->'rows')<>1
 or jsonb_typeof(p_input->'clientActionId') is distinct from 'string'
 or jsonb_typeof(p_input->'clientWriteMode') is distinct from 'string'
 or p_input->>'clientWriteMode' not in ('create','edit') then raise exception 'Invalid customer write' using errcode='22023';end if;
 aid:=(p_input->>'clientActionId')::uuid;
 if aid is null then raise exception 'Missing action' using errcode='22023';end if;
 r:=p_input->'rows'->0;mode:=p_input->>'clientWriteMode';
 if jsonb_typeof(r) is distinct from 'object' or (r-array['id','name','email','phone','notes','archived','identification','tradeName','group','address'])<>'{}'::jsonb
 or not(r ?& array['id','name','email','phone','notes','archived']) or jsonb_typeof(r->'archived') is distinct from 'boolean' then raise exception 'Invalid customer row' using errcode='22023';end if;
 foreach field in array array['id','name','email','phone','notes','identification','tradeName','group','address'] loop
  if (field=any(array['id','name','email','phone','notes']) or r ? field) and
  (jsonb_typeof(r->field) is distinct from 'string' or length(r->>field)>(case field when 'phone' then 30 when 'notes' then 2000 when 'identification' then 12 when 'group' then 80 when 'address' then 500 when 'email' then 16000 else 160 end)) then raise exception 'Invalid customer field' using errcode='22023';end if;
 end loop;
 if length(btrim(r->>'id'))=0 or btrim(r->>'id')<>r->>'id' or length(btrim(r->>'name'))=0 or btrim(r->>'name')<>r->>'name'
 or r ? 'identification' and (r->>'identification')!~'^[0-9]{0,12}$'
 or mode='create' and ((r->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or r->'archived'<>'false'::jsonb)
 then raise exception 'Invalid customer identity' using errcode='22023';end if;
 -- Same owner advisory and row-CAS order as pro_mutate_catalog. A replay is
 -- checked BEFORE mutable row existence/revision so a saved edit is never redone.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into prior from pro_client_write_actions where actor_id=p_actor and action_id=aid;
 if found then
  if prior.input is distinct from p_input then raise exception 'Customer action changed' using errcode='40001';end if;
  return prior.result;
 end if;
 if mode='create' and exists(select 1 from pro_clients where user_id=p_actor and id=r->>'id')
 or mode='edit' and not exists(select 1 from pro_clients where user_id=p_actor and id=r->>'id') then raise exception 'Customer changed' using errcode='40001';end if;
 v:=pro_mutate_catalog(p_actor,'clients',p_input->'rows',(p_input->>'revision')::integer,'[]'::jsonb,false);
 result:=jsonb_build_object('id',r->>'id','revision',v);
 insert into pro_client_write_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
revoke all on function public.pro_client_write_record(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_write_record(uuid,jsonb) to service_role;
commit;
notify pgrst,'reload schema';

-- ===== inventory-write-recovery-local.sql =====
-- LOCAL PRO ONLY. Additive one-product/stock receipts; no backfill or legacy contract change.
begin;
create table if not exists public.pro_inventory_write_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input jsonb not null,result jsonb not null,
 primary key(actor_id,action_id)
);
alter table public.pro_inventory_write_actions enable row level security;
revoke all on public.pro_inventory_write_actions from public,anon,authenticated;
grant all on public.pro_inventory_write_actions to service_role;
create or replace function public.pro_inventory_write_record(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior pro_inventory_write_actions;aid uuid;r jsonb;m jsonb;field text;v integer;result jsonb;mode text;movement_id uuid;
begin
 if p_actor is null then raise exception 'Missing actor' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object'
 or (p_input-array['kind','revision','rows','movements','importing','inventoryActionId','inventoryWriteMode'])<>'{}'::jsonb
 or not(p_input ?& array['kind','revision','rows','movements','importing','inventoryActionId','inventoryWriteMode'])
 or p_input->'kind' is distinct from '"products"'::jsonb or p_input->'importing' is distinct from 'false'::jsonb
 or jsonb_typeof(p_input->'movements') is distinct from 'array'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,10}$'
 or jsonb_typeof(p_input->'rows') is distinct from 'array' then raise exception 'Invalid inventory write' using errcode='22023';end if;
 if (p_input->>'revision')::bigint>2147483646 or jsonb_array_length(p_input->'rows')<>1 or jsonb_array_length(p_input->'movements')>1
 or jsonb_typeof(p_input->'inventoryActionId') is distinct from 'string'
 or jsonb_typeof(p_input->'inventoryWriteMode') is distinct from 'string'
 or p_input->>'inventoryWriteMode' not in ('create','edit','movement') then raise exception 'Invalid inventory write' using errcode='22023';end if;
 aid:=(p_input->>'inventoryActionId')::uuid;
 if aid is null then raise exception 'Missing action' using errcode='22023';end if;
 r:=p_input->'rows'->0;mode:=p_input->>'inventoryWriteMode';
 if jsonb_typeof(r) is distinct from 'object' or (r-array['id','sku','name','stock','minimum','cost','price','archived','category','unit','cabys','itemType'])<>'{}'::jsonb
 or not(r ?& array['id','sku','name','stock','minimum','cost','price','archived']) or jsonb_typeof(r->'archived') is distinct from 'boolean' then raise exception 'Invalid inventory row' using errcode='22023';end if;
 foreach field in array array['id','sku','name','category','unit','cabys','itemType'] loop
  if (field=any(array['id','sku','name']) or r ? field) and
  (jsonb_typeof(r->field) is distinct from 'string' or length(r->>field)>(case field when 'unit' then 30 when 'cabys' then 13 else 160 end)) then raise exception 'Invalid inventory field' using errcode='22023';end if;
 end loop;
 foreach field in array array['stock','minimum','cost','price'] loop
  if jsonb_typeof(r->field) is distinct from 'number' or (r->>field)::numeric<0 then raise exception 'Invalid inventory amount' using errcode='22023';end if;
 end loop;
 if length(btrim(r->>'id'))=0 or btrim(r->>'id')<>r->>'id' or length(btrim(r->>'sku'))=0 or btrim(r->>'sku')<>r->>'sku' or length(btrim(r->>'name'))=0 or btrim(r->>'name')<>r->>'name'
 or r ? 'cabys' and (r->>'cabys')!~'^(|[0-9]{13})$'
 or r ? 'itemType' and r->>'itemType' not in ('product','service')
 or mode='create' and ((r->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or r->'archived'<>'false'::jsonb)
 or (mode='movement') is distinct from (jsonb_array_length(p_input->'movements')=1)
 then raise exception 'Invalid inventory identity' using errcode='22023';end if;
 if mode='movement' then
  m:=p_input->'movements'->0;
  if jsonb_typeof(m) is distinct from 'object' or (m-array['id','productId','delta','reason','at'])<>'{}'::jsonb
  or not(m ?& array['id','productId','delta','reason','at'])
  or jsonb_typeof(m->'id') is distinct from 'string' or jsonb_typeof(m->'productId') is distinct from 'string' or m->'productId' is distinct from r->'id'
  or jsonb_typeof(m->'delta') is distinct from 'number' or (m->>'delta')::numeric=0
  or jsonb_typeof(m->'reason') is distinct from 'string' or length(btrim(m->>'reason')) not between 1 and 160 or btrim(m->>'reason')<>m->>'reason'
  or jsonb_typeof(m->'at') is distinct from 'string' or length(m->>'at')>40 or (m->>'at')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
  or r->'archived'<>'false'::jsonb or r->>'itemType'='service' then raise exception 'Invalid inventory movement' using errcode='22023';end if;
  movement_id:=(m->>'id')::uuid;
  if movement_id is null or not isfinite((m->>'at')::timestamptz) then raise exception 'Invalid movement identity' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 -- Replay wins before current stock, archive, row existence and global revision.
 select * into prior from pro_inventory_write_actions where actor_id=p_actor and action_id=aid;
 if found then
  if prior.input is distinct from p_input then raise exception 'Inventory action changed' using errcode='40001';end if;
  return prior.result;
 end if;
 if mode='create' and exists(select 1 from pro_products where user_id=p_actor and id=r->>'id')
 or mode<>'create' and not exists(select 1 from pro_products where user_id=p_actor and id=r->>'id') then raise exception 'Inventory changed' using errcode='40001';end if;
 -- The established writer owns all stock equality/rounding, immutable type,
 -- service/no-stock, unique SKU, movement history and nonnegative constraints.
 v:=pro_mutate_catalog(p_actor,'products',p_input->'rows',(p_input->>'revision')::integer,p_input->'movements',false);
 result:=jsonb_build_object('id',r->>'id','revision',v,'movementId',movement_id);
 insert into pro_inventory_write_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
revoke all on function public.pro_inventory_write_record(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_inventory_write_record(uuid,jsonb) to service_role;
commit;
notify pgrst,'reload schema';

-- ===== promotion-records-draft.sql =====
-- LOCAL ONLY. No remote migration has been created or applied.
-- Diffusion is an immutable admin audit event, not a subscription quota.
create unique index if not exists pro_promotion_request_unique
on public.pro_audit ((detail->>'requestId'))
where action='publication_promotion';

-- ===== work-tasks-local.sql =====
-- Pro local only. Private normalized job tasks; no workspace JSON writes.
-- Apply only to the isolated local database after preserving existing data.
begin;
create table if not exists public.pro_work_tasks(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 work_id text not null check(length(work_id) between 1 and 160),id uuid not null,
 title text not null check(length(btrim(title)) between 1 and 160),
 details text not null default '' check(length(details)<=2000),
 due_date date check(due_date between date '1900-01-01' and date '2100-12-31'),
 assignee text not null default '' check(length(assignee)<=160),
 status text not null default 'open' check(status in('open','done')),
 archived boolean not null default false,revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,work_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_tasks_page on public.pro_work_tasks(owner_id,work_id,archived,status,due_date,id);
create index if not exists pro_work_tasks_all_page on public.pro_work_tasks(owner_id,work_id,archived,due_date,id);
create table if not exists public.pro_work_task_history(
 owner_id uuid not null,work_id text not null,task_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','complete','reopen','archive','restore')),
 before_task jsonb,after_task jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade
);
create index if not exists pro_work_task_history_page on public.pro_work_task_history(owner_id,work_id,task_id,((after_task->>'revision')::integer) desc);
create table if not exists public.pro_work_task_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create or replace function public.pro_work_task_json(p_task public.pro_work_tasks) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_task.id,'workId',p_task.work_id,'title',p_task.title,'details',p_task.details,
 'dueDate',case when p_task.due_date is null then null else to_char(p_task.due_date,'YYYY-MM-DD') end,
 'assignee',p_task.assignee,'status',p_task.status,'archived',p_task.archived,'revision',p_task.revision,
 'createdAt',p_task.created_at,'updatedAt',p_task.updated_at);
$$;
create or replace function public.pro_work_tasks_read(p_actor uuid,p_work text,p_status text default 'open',p_after uuid default null,p_archived boolean default false,p_task uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare task public.pro_work_tasks;items jsonb;hist jsonb;cursor_id uuid;cursor_due date;open_count integer;done_count integer;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_status is null or p_status not in('open','done','all') or p_archived is null then raise exception 'Invalid task query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 if p_task is not null then
  select * into task from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and id=p_task;
  if not found then return null;end if;
  select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
   select (h.after_task->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'at',h.at,'action',h.action,'before',h.before_task,'after',h.after_task) as content
   from public.pro_work_task_history h where h.owner_id=p_actor and h.work_id=p_work and h.task_id=p_task order by (h.after_task->>'revision')::integer desc limit 20
  ) x;
  return jsonb_build_object('task',public.pro_work_task_json(task),'history',hist);
 end if;
 if p_after is not null then
  select coalesce(due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and id=p_after;
  if not found then raise exception 'Invalid task cursor' using errcode='22023';end if;
 end if;
 select count(*) filter(where status='open'),count(*) filter(where status='done') into open_count,done_count from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and not archived;
 select coalesce(jsonb_agg(public.pro_work_task_json(t::public.pro_work_tasks) order by t.due_date asc nulls last,t.id),'[]'::jsonb) into items from (
  select * from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and archived=p_archived and (p_status='all' or status=p_status) and (p_after is null or (coalesce(due_date,date '9999-12-31'),id)>(cursor_due,p_after)) order by due_date asc nulls last,id limit 21
 ) t;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count));
end $$;
create or replace function public.pro_work_tasks_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;tid uuid;aid uuid;act text;rev integer;keys text[];receipt public.pro_work_task_actions;task public.pro_work_tasks;before_json jsonb;after_json jsonb;result jsonb;due date;task_title text;task_details text;task_assignee text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid task' using errcode='22023';end if;
 act:=p_input->>'action';wid:=p_input->>'workId';
 if act is null or act not in('create','update','complete','reopen','archive','restore') or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160
 or jsonb_typeof(p_input->'taskId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false)
 then raise exception 'Invalid task identity' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 tid:=(p_input->>'taskId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act in('create','update') then
  if keys<>array['action','actionId','assignee','details','dueDate','revision','taskId','title','workId']
   or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'details') is distinct from 'string' or jsonb_typeof(p_input->'assignee') is distinct from 'string'
   or not coalesce(jsonb_typeof(p_input->'dueDate') in('null','string'),false)
  then raise exception 'Invalid task fields' using errcode='22023';end if;
  task_title:=btrim(p_input->>'title');task_details:=btrim(p_input->>'details');task_assignee:=btrim(p_input->>'assignee');
  if length(task_title) not between 1 and 160 or length(task_details)>2000 or length(task_assignee)>160 then raise exception 'Invalid task text' using errcode='22023';end if;
  if p_input->'dueDate'<>'null'::jsonb then
   if not coalesce((p_input->>'dueDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid date' using errcode='22023';end if;
   due:=(p_input->>'dueDate')::date;
   if due<date '1900-01-01' or due>date '2100-12-31' or to_char(due,'YYYY-MM-DD')<>p_input->>'dueDate' then raise exception 'Invalid date' using errcode='22023';end if;
  end if;
 else
  if keys<>array['action','actionId','revision','taskId','workId'] then raise exception 'Unexpected task fields' using errcode='22023';end if;
 end if;
 -- Action identity is serialized first, including concurrent retries for two jobs.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-task-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_task_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into task from public.pro_work_tasks where owner_id=p_actor and id=tid for update;
 if act='create' then
  if rev<>0 then raise exception 'Create requires zero revision' using errcode='22023';end if;
  if found then raise exception 'Task identity already exists' using errcode='22023';end if;
  if (select count(*) from public.pro_work_tasks where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Task limit reached' using errcode='54000';end if;
  insert into public.pro_work_tasks(owner_id,work_id,id,title,details,due_date,assignee) values(p_actor,wid,tid,task_title,task_details,due,task_assignee) returning * into task;
 else
  if not found or task.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if rev<>task.revision then raise exception 'Task changed' using errcode='40001';end if;
  before_json:=public.pro_work_task_json(task);
  if act='update' then
   if task.archived then raise exception 'Restore task before editing' using errcode='22023';end if;
   update public.pro_work_tasks set title=task_title,details=task_details,due_date=due,assignee=task_assignee,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  elsif act in('complete','reopen') then
   if task.archived or (act='complete' and task.status<>'open') or (act='reopen' and task.status<>'done') then raise exception 'Invalid task transition' using errcode='22023';end if;
   update public.pro_work_tasks set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  elsif act in('archive','restore') then
   if task.archived=(act='archive') then raise exception 'Invalid archive transition' using errcode='22023';end if;
   update public.pro_work_tasks set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  end if;
 end if;
 after_json:=public.pro_work_task_json(task);result:=jsonb_build_object('task',after_json);
 insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(p_actor,wid,tid,aid,act,before_json,after_json);
 insert into public.pro_work_task_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_task_history_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Task history is immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_task_history_immutable on public.pro_work_task_history;
create trigger pro_work_task_history_immutable before update on public.pro_work_task_history for each row execute function public.pro_work_task_history_immutable();
drop trigger if exists pro_work_task_action_immutable on public.pro_work_task_actions;
create trigger pro_work_task_action_immutable before update on public.pro_work_task_actions for each row execute function public.pro_work_task_history_immutable();
alter table public.pro_work_tasks enable row level security;
alter table public.pro_work_task_history enable row level security;
alter table public.pro_work_task_actions enable row level security;
revoke all on public.pro_work_tasks,public.pro_work_task_history,public.pro_work_task_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_tasks,public.pro_work_task_history,public.pro_work_task_actions to service_role;
revoke all on function public.pro_work_task_json(public.pro_work_tasks),public.pro_work_tasks_read(uuid,text,text,uuid,boolean,uuid),public.pro_work_tasks_mutate(uuid,jsonb),public.pro_work_task_history_immutable() from public,anon,authenticated;
grant execute on function public.pro_work_task_json(public.pro_work_tasks),public.pro_work_tasks_read(uuid,text,text,uuid,boolean,uuid),public.pro_work_tasks_mutate(uuid,jsonb) to service_role;
commit;

-- ===== task-center-local.sql =====
-- LOCAL PRO ONLY. Read-only cross-job task center and job picker.
-- Reuses normalized tasks/jobs, does not create, migrate or update any record.
begin;
create index if not exists pro_task_center_owner_due_page on public.pro_work_tasks(owner_id,due_date asc nulls last,id) where not archived;
create or replace function public.pro_task_center_read(p_actor uuid,p_status text default 'open',p_timing text default 'all',p_query text default '',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today_cr date:=(now() at time zone 'America/Costa_Rica')::date;needle text;cursor_due date;cursor_id uuid;items jsonb;open_count integer;done_count integer;overdue_count integer;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('open','done','all') or p_timing is null or p_timing not in('all','overdue','today','upcoming') or p_query is null or length(p_query)>100 then raise exception 'Invalid task-center query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 -- Literal substring matching: percent/underscore never become SQL wildcards.
 select count(*) filter(where t.status='open'),count(*) filter(where t.status='done'),count(*) filter(where t.status='open' and t.due_date<today_cr)
 into open_count,done_count,overdue_count from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
 where t.owner_id=p_actor and not t.archived and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0);
 if p_after is not null then
  select coalesce(t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and t.id=p_after and not t.archived and (p_status='all' or t.status=p_status)
  and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end;
  if not found then raise exception 'Task-center cursor changed; refresh the list' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('task',public.pro_work_task_json(x.task),'work',jsonb_build_object('id',x.work_id,'service',x.service,'client',x.client,'stage',x.stage,'cancelled',x.cancelled)) order by (x.task).due_date asc nulls last,(x.task).id),'[]'::jsonb) into items from (
  select t as task,w.id as work_id,w.service,w.client,w.stage,coalesce(w.cancelled,false) as cancelled
  from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and not t.archived and (p_status='all' or t.status=p_status)
  and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end
  and (p_after is null or (coalesce(t.due_date,date '9999-12-31'),t.id)>(cursor_due,p_after))
  order by t.due_date asc nulls last,t.id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'task'->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count,'overdue',overdue_count));
end $$;
create or replace function public.pro_task_center_jobs_read(p_actor uuid,p_query text default '',p_after text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare needle text;items jsonb;cursor_id text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_query is null or length(p_query)>100 or p_after is not null and length(p_after) not between 1 and 160 then raise exception 'Invalid job-picker query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 if p_after is not null and not exists(select 1 from public.pro_work where user_id=p_actor and id=p_after and not coalesce(cancelled,false)
 and (needle='' or position(needle in lower(service))>0 or position(needle in lower(client))>0)) then raise exception 'Job-picker cursor changed; refresh the list' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'service',w.service,'client',w.client,'start',w.start,'stage',w.stage,'cancelled',false) order by w.id),'[]'::jsonb) into items from (
  select id,service,client,start,stage from public.pro_work where user_id=p_actor and not coalesce(cancelled,false)
  and (needle='' or position(needle in lower(service))>0 or position(needle in lower(client))>0) and (p_after is null or id>p_after) order by id limit 21
 ) w;
 if jsonb_array_length(items)>20 then cursor_id:=items->19->>'id';items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
revoke all on function public.pro_task_center_read(uuid,text,text,text,uuid),public.pro_task_center_jobs_read(uuid,text,text) from public,anon,authenticated;
grant execute on function public.pro_task_center_read(uuid,text,text,text,uuid),public.pro_task_center_jobs_read(uuid,text,text) to service_role;
commit;

-- ===== request-followups-local.sql =====
-- LOCAL PRO ONLY. Additive private follow-up on existing customer requests.
-- Does not alter request data, create messages, notifications, charges or jobs.
begin;
-- Existing request IDs are unique; the additional owner identity supports a scoped FK.
create unique index if not exists pro_appointment_request_owner_identity on public.pro_appointment_requests(owner_id,id);
create table if not exists public.pro_request_followups(
 owner_id uuid not null,request_id uuid not null,
 due_date date check(due_date between date '1900-01-01' and date '2100-12-31'),
 note text not null default '' check(length(note)<=1000),
 status text not null default 'open' check(status in('open','done')),
 revision integer not null check(revision>0),updated_at timestamptz not null default now(),
 primary key(owner_id,request_id),
 foreign key(owner_id,request_id) references public.pro_appointment_requests(owner_id,id) on delete cascade
);
create index if not exists pro_request_followups_upcoming on public.pro_request_followups(owner_id,due_date,request_id) where status='open' and due_date is not null;
create table if not exists public.pro_request_followup_history(
 owner_id uuid not null,request_id uuid not null,action_id uuid not null,
 action text not null check(action in('save','complete','reopen')),
 before_followup jsonb,after_followup jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),
 foreign key(owner_id,request_id) references public.pro_request_followups(owner_id,request_id) on delete cascade
);
create index if not exists pro_request_followup_history_page on public.pro_request_followup_history(owner_id,request_id,((after_followup->>'revision')::integer) desc);
create table if not exists public.pro_request_followup_actions(
 actor_id uuid not null,action_id uuid not null,request_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(actor_id,request_id) references public.pro_appointment_requests(owner_id,id) on delete cascade
);
create or replace function public.pro_request_followup_json(p_followup public.pro_request_followups,p_request uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('requestId',p_request,'dueDate',case when p_followup.due_date is null then null else to_char(p_followup.due_date,'YYYY-MM-DD') end,
 'note',coalesce(p_followup.note,''),'status',coalesce(p_followup.status,'open'),'revision',coalesce(p_followup.revision,0),'updatedAt',p_followup.updated_at);
$$;
create or replace function public.pro_request_followup_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare followup public.pro_request_followups;hist jsonb;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_appointment_requests where id=p_request and owner_id=p_actor) then return null;end if;
 select * into followup from public.pro_request_followups where owner_id=p_actor and request_id=p_request;
 select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
  select (h.after_followup->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_followup,'after',h.after_followup) as content
  from public.pro_request_followup_history h where h.owner_id=p_actor and h.request_id=p_request order by (h.after_followup->>'revision')::integer desc limit 20
 ) x;
 return jsonb_build_object('followup',public.pro_request_followup_json(followup,p_request),'history',hist);
end $$;
create or replace function public.pro_request_followups_upcoming(p_actor uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare cursor_due date;items jsonb;cursor_id uuid;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null then
  select due_date into cursor_due from public.pro_request_followups where owner_id=p_actor and request_id=p_after;
  if not found or cursor_due is null then raise exception 'Invalid follow-up cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(x.content order by x.due_date,x.request_id),'[]'::jsonb) into items from (
  select f.due_date,f.request_id,public.pro_request_followup_json(f,f.request_id)||jsonb_build_object('service',r.service,'clientName',r.client_name) as content
  from public.pro_request_followups f join public.pro_appointment_requests r on r.owner_id=f.owner_id and r.id=f.request_id
  where f.owner_id=p_actor and f.status='open' and f.due_date is not null and (p_after is null or (f.due_date,f.request_id)>(cursor_due,p_after))
  order by f.due_date,f.request_id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'requestId')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_request_followup_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare rid uuid;aid uuid;act text;rev integer;keys text[];receipt public.pro_request_followup_actions;followup public.pro_request_followups;exists_followup boolean;before_json jsonb;after_json jsonb;result jsonb;due date;followup_note text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid follow-up' using errcode='22023';end if;
 act:=p_input->>'action';
 if act is null or act not in('save','complete','reopen') or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid identity' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 rid:=(p_input->>'requestId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act='save' then
  if keys<>array['action','actionId','dueDate','note','requestId','revision'] or jsonb_typeof(p_input->'note') is distinct from 'string' or not coalesce(jsonb_typeof(p_input->'dueDate') in('null','string'),false) then raise exception 'Invalid follow-up fields' using errcode='22023';end if;
  followup_note:=btrim(p_input->>'note');if length(followup_note)>1000 then raise exception 'Note too long' using errcode='22023';end if;
  if p_input->'dueDate'<>'null'::jsonb then
   if not coalesce((p_input->>'dueDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid date' using errcode='22023';end if;
   due:=(p_input->>'dueDate')::date;
   if due<date '1900-01-01' or due>date '2100-12-31' or to_char(due,'YYYY-MM-DD')<>p_input->>'dueDate' then raise exception 'Invalid date' using errcode='22023';end if;
  end if;
 else
  if keys<>array['action','actionId','requestId','revision'] or rev=0 then raise exception 'Invalid follow-up action' using errcode='22023';end if;
 end if;
 if not exists(select 1 from public.pro_appointment_requests where id=rid and owner_id=p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-request-followup-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_request_followup_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-request-followup:'||p_actor::text||':'||rid::text,0));
 select * into followup from public.pro_request_followups where owner_id=p_actor and request_id=rid for update;
 exists_followup:=found;
 if not exists_followup then
  if act<>'save' or rev<>0 then raise exception 'Follow-up changed' using errcode='40001';end if;
  insert into public.pro_request_followups(owner_id,request_id,due_date,note,status,revision) values(p_actor,rid,due,followup_note,'open',1) returning * into followup;
 else
  if rev<>followup.revision then raise exception 'Follow-up changed' using errcode='40001';end if;
  before_json:=public.pro_request_followup_json(followup,rid);
  if act='save' then
   update public.pro_request_followups set due_date=due,note=followup_note,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=rid returning * into followup;
  else
   if (act='complete' and followup.status<>'open') or (act='reopen' and followup.status<>'done') then raise exception 'Invalid follow-up transition' using errcode='22023';end if;
   update public.pro_request_followups set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=rid returning * into followup;
  end if;
 end if;
 after_json:=public.pro_request_followup_json(followup,rid);result:=jsonb_build_object('followup',after_json);
 insert into public.pro_request_followup_history(owner_id,request_id,action_id,action,before_followup,after_followup) values(p_actor,rid,aid,act,before_json,after_json);
 insert into public.pro_request_followup_actions(actor_id,action_id,request_id,input,result) values(p_actor,aid,rid,p_input,result);
 return result;
end $$;
create or replace function public.pro_request_followup_history_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Follow-up history is immutable' using errcode='23514';end $$;
drop trigger if exists pro_request_followup_history_immutable on public.pro_request_followup_history;
create trigger pro_request_followup_history_immutable before update on public.pro_request_followup_history for each row execute function public.pro_request_followup_history_immutable();
drop trigger if exists pro_request_followup_action_immutable on public.pro_request_followup_actions;
create trigger pro_request_followup_action_immutable before update on public.pro_request_followup_actions for each row execute function public.pro_request_followup_history_immutable();
alter table public.pro_request_followups enable row level security;
alter table public.pro_request_followup_history enable row level security;
alter table public.pro_request_followup_actions enable row level security;
revoke all on public.pro_request_followups,public.pro_request_followup_history,public.pro_request_followup_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_request_followups,public.pro_request_followup_history,public.pro_request_followup_actions to service_role;
revoke all on function public.pro_request_followup_json(public.pro_request_followups,uuid),public.pro_request_followup_read(uuid,uuid),public.pro_request_followups_upcoming(uuid,uuid),public.pro_request_followup_mutate(uuid,jsonb),public.pro_request_followup_history_immutable() from public,anon,authenticated;
grant execute on function public.pro_request_followup_json(public.pro_request_followups,uuid),public.pro_request_followup_read(uuid,uuid),public.pro_request_followups_upcoming(uuid,uuid),public.pro_request_followup_mutate(uuid,jsonb) to service_role;
commit;

-- ===== work-updates-local.sql =====
-- LOCAL PRO ONLY. Private text progress with explicitly shared immutable snapshots.
-- No changes to work/delivery/request records, storage buckets, messages or outboxes.
begin;
create table if not exists public.pro_work_updates(
 owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,id uuid not null,
 title text not null check(length(btrim(title)) between 1 and 160),text text not null check(length(btrim(text)) between 1 and 2000),
 revision integer not null default 1 check(revision>0),published_revision integer check(published_revision>0 and published_revision<=revision),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,work_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_updates_page on public.pro_work_updates(owner_id,work_id,created_at desc,id desc);
create table if not exists public.pro_work_update_history(
 owner_id uuid not null,work_id text not null,entry_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','publish')),before_entry jsonb,after_entry jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),foreign key(owner_id,work_id,entry_id) references public.pro_work_updates(owner_id,work_id,id) on delete cascade
);
create index if not exists pro_work_update_history_page on public.pro_work_update_history(owner_id,work_id,entry_id,((after_entry->>'revision')::integer) desc);
create table if not exists public.pro_work_update_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create table if not exists public.pro_work_update_versions(
 owner_id uuid not null,work_id text not null,entry_id uuid not null,version integer not null check(version>0),
 client_user_id uuid not null references public.profiles(id) on delete cascade,recipient_name text not null check(length(recipient_name) between 1 and 160),entry_revision integer not null check(entry_revision>0),
 title text not null check(length(btrim(title)) between 1 and 160),text text not null check(length(btrim(text)) between 1 and 2000),
 service text not null check(length(service) between 1 and 160),published_at timestamptz not null default now(),entry_created_at timestamptz not null,
 primary key(owner_id,entry_id,version),unique(owner_id,entry_id,entry_revision),foreign key(owner_id,work_id,entry_id) references public.pro_work_updates(owner_id,work_id,id) on delete cascade
);
create index if not exists pro_work_update_versions_client_page on public.pro_work_update_versions(client_user_id,owner_id,work_id,entry_created_at desc,entry_id desc,version desc);
create or replace function public.pro_work_update_json(p_entry public.pro_work_updates) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_entry.id,'workId',p_entry.work_id,'title',p_entry.title,'text',p_entry.text,'revision',p_entry.revision,
 'publishedRevision',p_entry.published_revision,'createdAt',p_entry.created_at,'updatedAt',p_entry.updated_at);
$$;
create or replace function public.pro_work_update_can_share(p_actor uuid,p_work text) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(select 1 from public.pro_work w join public.pro_appointment_requests r on r.owner_id=w.user_id and r.work_id=w.id
 join public.profiles c on c.id=r.client_user_id where w.user_id=p_actor and w.id=p_work and not coalesce(w.cancelled,false)
 and r.status in('confirmed','completed') and not coalesce(c.is_disabled,false));
$$;
create or replace function public.pro_work_updates_read(p_actor uuid,p_work text,p_after uuid default null,p_entry uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare entry public.pro_work_updates;items jsonb;hist jsonb;cursor_time timestamptz;cursor_id uuid;can_share boolean;recipient uuid;recipient_name text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_after is not null and p_entry is not null then raise exception 'Invalid progress query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 can_share:=public.pro_work_update_can_share(p_actor,p_work);
 if can_share then
  select ar.client_user_id,ar.client_name into recipient,recipient_name from public.pro_appointment_requests ar join public.profiles c on c.id=ar.client_user_id
   where ar.owner_id=p_actor and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(c.is_disabled,false);
 end if;
 if p_entry is not null then
  select * into entry from public.pro_work_updates where owner_id=p_actor and work_id=p_work and id=p_entry;
  if not found then return null;end if;
  select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
   select (h.after_entry->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_entry,'after',h.after_entry) as content
   from public.pro_work_update_history h where h.owner_id=p_actor and h.work_id=p_work and h.entry_id=p_entry order by (h.after_entry->>'revision')::integer desc limit 20
  ) x;
  return jsonb_build_object('entry',public.pro_work_update_json(entry),'history',hist,'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
 end if;
 if p_after is not null then
  select created_at into cursor_time from public.pro_work_updates where owner_id=p_actor and work_id=p_work and id=p_after;
  if not found then raise exception 'Invalid progress cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(public.pro_work_update_json(e::public.pro_work_updates) order by e.created_at desc,e.id desc),'[]'::jsonb) into items from (
  select * from public.pro_work_updates where owner_id=p_actor and work_id=p_work and (p_after is null or (created_at,id)<(cursor_time,p_after)) order by created_at desc,id desc limit 21
 ) e;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id,'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
end $$;
create or replace function public.pro_work_updates_client_read(p_actor uuid,p_request uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;cursor_time timestamptz;cursor_id uuid;items jsonb;
begin
 -- Shared history remains readable without a Pro membership on either account.
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id into owner,wid from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 if p_after is not null then
  select entry_created_at into cursor_time from public.pro_work_update_versions where owner_id=owner and work_id=wid and client_user_id=p_actor and entry_id=p_after order by version desc limit 1;
  if not found then raise exception 'Invalid shared progress cursor' using errcode='22023';end if;
 end if;
 -- Filter recipient before taking latest; never read a private draft into this view.
 with latest as (
  select distinct on(v.entry_id) v.* from public.pro_work_update_versions v where v.owner_id=owner and v.work_id=wid and v.client_user_id=p_actor order by v.entry_id,v.version desc
 )
 select coalesce(jsonb_agg(x.content order by x.entry_created_at desc,x.entry_id desc),'[]'::jsonb) into items from (
  select v.entry_created_at,v.entry_id,jsonb_build_object('id',v.entry_id,'version',v.version,'title',v.title,'text',v.text,'publishedAt',v.published_at,'service',v.service) as content
  from latest v where p_after is null or (v.entry_created_at,v.entry_id)<(cursor_time,p_after) order by v.entry_created_at desc,v.entry_id desc limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_work_updates_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;eid uuid;aid uuid;act text;rev integer;keys text[];receipt public.pro_work_update_actions;entry public.pro_work_updates;w public.pro_work;r public.pro_appointment_requests;before_json jsonb;after_json jsonb;result jsonb;entry_title text;entry_text text;recipient uuid;publication integer;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid progress' using errcode='22023';end if;
 act:=p_input->>'action';wid:=p_input->>'workId';
 if act is null or act not in('create','update','publish') or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160
 or jsonb_typeof(p_input->'entryId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid progress identity' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 eid:=(p_input->>'entryId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act in('create','update') then
  if keys<>array['action','actionId','entryId','revision','text','title','workId'] or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'text') is distinct from 'string' then raise exception 'Invalid progress fields' using errcode='22023';end if;
  entry_title:=btrim(p_input->>'title');entry_text:=btrim(p_input->>'text');
  if length(entry_title) not between 1 and 160 or length(entry_text) not between 1 and 2000 then raise exception 'Invalid progress text' using errcode='22023';end if;
 else
  if keys<>array['action','actionId','entryId','recipientId','revision','workId'] or jsonb_typeof(p_input->'recipientId') is distinct from 'string' then raise exception 'Unexpected progress fields' using errcode='22023';end if;
  recipient:=(p_input->>'recipientId')::uuid;
 end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-update-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_update_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-updates:'||p_actor::text||':'||wid,0));
 -- Match appointment cancel/reschedule ordering: request first, then work.
 -- A private create/update never locks the request. Receipt replay above never
 -- re-targets an already committed publication to a newly linked customer.
 if act='publish' then
  select ar.* into r from public.pro_appointment_requests ar where ar.owner_id=p_actor and ar.work_id=wid for share of ar;
  if not found then raise exception 'No linked customer' using errcode='42501';end if;
 end if;
 select * into w from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into entry from public.pro_work_updates where owner_id=p_actor and id=eid for update;
 if act='create' then
  if rev<>0 then raise exception 'Create requires zero revision' using errcode='22023';end if;
  if found then raise exception 'Progress identity already exists' using errcode='22023';end if;
  if (select count(*) from public.pro_work_updates where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Progress entry limit' using errcode='54000';end if;
  insert into public.pro_work_updates(owner_id,work_id,id,title,text) values(p_actor,wid,eid,entry_title,entry_text) returning * into entry;
 else
  if not found or entry.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if rev<>entry.revision then raise exception 'Progress changed' using errcode='40001';end if;
  before_json:=public.pro_work_update_json(entry);
  if act='update' then
   update public.pro_work_updates set title=entry_title,text=entry_text,revision=revision+1,updated_at=now() where owner_id=p_actor and id=eid returning * into entry;
  else
   if entry.published_revision is not distinct from entry.revision then raise exception 'No private changes to share' using errcode='22023';end if;
   if coalesce(w.cancelled,false) then raise exception 'Cancelled job cannot share progress' using errcode='42501';end if;
   if r.client_user_id<>recipient then raise exception 'The share recipient changed' using errcode='40001';end if;
   if r.status not in('confirmed','completed') or not exists(select 1 from public.profiles where id=r.client_user_id and not coalesce(is_disabled,false)) then raise exception 'No linked confirmed customer' using errcode='42501';end if;
   update public.pro_work_updates set revision=revision+1,published_revision=revision+1,updated_at=now() where owner_id=p_actor and id=eid returning * into entry;
   select coalesce(max(version),0)+1 into publication from public.pro_work_update_versions where owner_id=p_actor and entry_id=eid;
   insert into public.pro_work_update_versions(owner_id,work_id,entry_id,version,entry_revision,client_user_id,recipient_name,title,text,service,entry_created_at)
    values(p_actor,wid,eid,publication,entry.revision,r.client_user_id,r.client_name,entry.title,entry.text,w.service,entry.created_at);
  end if;
 end if;
 after_json:=public.pro_work_update_json(entry);result:=jsonb_build_object('entry',after_json);
 insert into public.pro_work_update_history(owner_id,work_id,entry_id,action_id,action,before_entry,after_entry) values(p_actor,wid,eid,aid,act,before_json,after_json);
 insert into public.pro_work_update_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_update_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Progress history and shared versions are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_update_history_immutable on public.pro_work_update_history;
create trigger pro_work_update_history_immutable before update on public.pro_work_update_history for each row execute function public.pro_work_update_immutable();
drop trigger if exists pro_work_update_action_immutable on public.pro_work_update_actions;
create trigger pro_work_update_action_immutable before update on public.pro_work_update_actions for each row execute function public.pro_work_update_immutable();
drop trigger if exists pro_work_update_version_immutable on public.pro_work_update_versions;
create trigger pro_work_update_version_immutable before update on public.pro_work_update_versions for each row execute function public.pro_work_update_immutable();
alter table public.pro_work_updates enable row level security;
alter table public.pro_work_update_history enable row level security;
alter table public.pro_work_update_actions enable row level security;
alter table public.pro_work_update_versions enable row level security;
revoke all on public.pro_work_updates,public.pro_work_update_history,public.pro_work_update_actions,public.pro_work_update_versions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_updates,public.pro_work_update_history,public.pro_work_update_actions,public.pro_work_update_versions to service_role;
revoke all on function public.pro_work_update_json(public.pro_work_updates),public.pro_work_update_can_share(uuid,text),public.pro_work_updates_read(uuid,text,uuid,uuid),public.pro_work_updates_client_read(uuid,uuid,uuid),public.pro_work_updates_mutate(uuid,jsonb),public.pro_work_update_immutable() from public,anon,authenticated;
grant execute on function public.pro_work_update_json(public.pro_work_updates),public.pro_work_update_can_share(uuid,text),public.pro_work_updates_read(uuid,text,uuid,uuid),public.pro_work_updates_client_read(uuid,uuid,uuid),public.pro_work_updates_mutate(uuid,jsonb) to service_role;
commit;
